  const open0 = XMLHttpRequest.prototype.open;
  XMLHttpRequest.prototype.open = function (m, url, ...rest) {
    try {
      const u = new URL(url, location.href);
      const c = u.searchParams.get('cameras');
      if (/\/api\/review$/.test(u.pathname) && u.searchParams.get('severity') === 'alert' && c && !c.split(',').includes(CAM)) {
        u.searchParams.set('cameras', c + ',' + CAM);
        url = u.pathname + '?' + u.searchParams.toString();
      }
    } catch (x) {}
    return open0.call(this, m, url, ...rest);
  };
  // the dashboard fetched its row before this ran: refetch (SWR revalidates on focus)
  setTimeout(() => window.dispatchEvent(new Event('focus')), 300);

  const row = document.createElement('div');
  row.id = '__ftv-door-alerts';
  row.style.cssText = 'position:fixed;z-index:2147482999;left:50%;top:8px;transform:translateX(-50%);display:none;gap:10px;'
    + 'padding:6px;border-radius:12px;background:rgba(0,0,0,.55);font:13px system-ui,sans-serif;color:#fff';
  let shown = '';
  const ago = s => { const m = Math.round((Date.now() / 1000 - s) / 60); return m < 60 ? m + 'm ago' : m < 1440 ? Math.round(m / 60) + 'h ago' : Math.round(m / 1440) + 'd ago'; };
  const openReview = it => {
    const st = { usr: { severity: 'alert', recording: { camera: CAM, startTime: it.start_time, severity: 'alert' } }, key: 'ftv' + Date.now(), idx: ((history.state && history.state.idx) || 0) + 1 };
    history.pushState(st, '', '/review');
    window.dispatchEvent(new PopStateEvent('popstate', { state: st }));
  };
  const load = () => {
    if (location.hash !== '#' + CAM) { row.style.display = 'none'; return; }
    const x = new XMLHttpRequest();
    open0.call(x, 'GET', '/api/review?cameras=' + CAM + '&severity=alert&limit=6');
    x.onload = () => {
      let items = [];
      try { items = JSON.parse(x.responseText) || []; } catch (e) {}
      const key = items.map(i => i.id).join();
      if (key !== shown) {
        shown = key;
        row.replaceChildren(...items.map(it => {
          const b = document.createElement('div');
          b.setAttribute('role', 'button'); b.tabIndex = 0;
          b.style.cssText = 'position:relative;width:160px;height:90px;border-radius:8px;overflow:hidden;cursor:pointer;'
            + 'background:#222 center/cover no-repeat;background-image:url("/clips/review/' + it.thumb_path.split('/').pop() + '")';
          const l = document.createElement('div');
          const what = ((it.data && it.data.objects) || []).map(o => o.split(':')[0])[0] || 'alert';
          l.textContent = what + ' · ' + ago(it.start_time);
          l.style.cssText = 'position:absolute;left:0;right:0;bottom:0;padding:2px 6px;background:rgba(0,0,0,.6)';
          b.append(l);
          b.addEventListener('click', () => openReview(it));
          return b;
        }));
      }
      row.style.display = items.length ? 'flex' : 'none';
      if (!row.isConnected) document.body.appendChild(row);
    };
    x.send();
  };
  window.addEventListener('hashchange', load);
  setInterval(load, 10000);
  load();
})();
