.lhead{display:flex;justify-content:space-between;gap:8px;font-family:var(--display);font-size:11px;color:#c9cde4;letter-spacing:.04em}
.lhead em{font-style:normal;color:#8f96b8}
.lhead b{font-weight:400;color:#ffd43b;font-variant-numeric:tabular-nums}
.lrow[data-s="fail"] .lhead b{color:#ff6b6b}
.lane{position:relative;height:50px;margin:0 46px 0 20px}
.pellets{position:absolute;inset:0;display:flex;justify-content:space-between;align-items:center}
.pellets i{width:6px;height:6px;background:var(--pellet);border-radius:1px;transition:opacity .2s,transform .2s}
.pellets i.big{width:10px;height:10px;border-radius:50%;animation:pulse 1s steps(2) infinite}
.pellets i.eaten{opacity:0;transform:scale(0)}
@keyframes pulse{50%{opacity:.35}}
.pac{--c:#ffd43b;position:absolute;top:50%;width:32px;height:32px;margin:-16px 0 0 -16px;left:0;transition:left 1.4s linear;z-index:2}
.pac::before,.pac::after{content:"";position:absolute;left:0;width:32px;height:16px;background:var(--c)}
.pac::before{top:0;border-radius:16px 16px 0 0;transform-origin:50% 100%;animation:jawT .28s linear infinite alternate}
.pac::after{bottom:0;border-radius:0 0 16px 16px;transform-origin:50% 0;animation:jawB .28s linear infinite alternate}
.lrow[data-s="queued"] .pac::before,.lrow[data-s="queued"] .pac::after,.lrow[data-s="fail"] .pac::before,.lrow[data-s="fail"] .pac::after{animation:none;transform:rotate(0)}
.lrow[data-s="queued"] .pac{opacity:.55}
.lrow[data-s="fail"] .pac{--c:#5b6bff}
@keyframes jawT{from{transform:rotate(-34deg)}to{transform:rotate(0)}}
@keyframes jawB{from{transform:rotate(34deg)}to{transform:rotate(0)}}
.pac .eye{position:absolute;top:5px;left:16px;width:4px;height:4px;background:#10131f;border-radius:50%;z-index:3}
.pac .acc{position:absolute;left:-6px;top:-14px;width:44px;height:52px;z-index:4;pointer-events:none;image-rendering:pixelated}
.target{position:absolute;right:-42px;top:50%;width:40px;height:28px;margin-top:-15px;transition:transform .5s,opacity .5s}
.target svg{width:100%;height:100%;image-rendering:pixelated}
.target .legs rect{animation:step .5s steps(1) infinite}
.target .legs rect:nth-child(even){animation-delay:.25s}
.lane.near .target{animation:shake .3s steps(3) infinite}
/* Death: Pac bites, Claude flashes, eyes go X, it melts flat, its soul floats off, +5000, R.I.P. */
.target .xeyes{display:none}
.lane.won .target .eyes2{display:none}
.lane.won .target .xeyes{display:inline}
.lane.won .target .legs rect{animation:none}
.lane.won .target svg{transform-origin:50% 100%;animation:hit .12s steps(1) 6,melt .9s 1s steps(6) forwards}
@keyframes hit{50%{filter:brightness(3) saturate(0)}}
@keyframes melt{0%{transform:scale(1,1)}40%{transform:scale(1.25,.6)}100%{transform:scale(1.5,.08)}}
.soul{position:absolute;right:-36px;top:-6px;width:28px;height:24px;opacity:0;pointer-events:none}
.lane.won .soul{animation:rise 2.4s 1.9s ease-out forwards}
@keyframes rise{0%{opacity:0;transform:translateY(10px)}20%{opacity:.9}100%{opacity:0;transform:translateY(-50px)}}
.score{position:absolute;right:-44px;top:0;font-family:var(--display);font-size:12px;color:#7df9ff;opacity:0}
.lane.won .score{animation:pop 1.6s .5s steps(8) forwards}
@keyframes pop{0%{opacity:1;transform:translateY(0)}80%{opacity:1}100%{opacity:0;transform:translateY(-16px)}}
.rip{position:absolute;right:-44px;bottom:-4px;font-family:var(--display);font-size:10px;color:#8f96b8;opacity:0}
.lane.won .rip{animation:fadein .6s 2.2s forwards}
@keyframes fadein{to{opacity:1}}
.lane.won .pac{animation:gulp .2s 6 steps(2)}
@keyframes gulp{50%{transform:scale(1.15)}}
.maze-foot{font-family:var(--mono);font-size:12px;color:#c9cde4}
