// @vitest-environment jsdom
import { afterEach, describe, expect, it } from 'vitest'
import { MODEL_ID, OpenClawChatGptAdapter } from '../src/adapter.ts'
import { resolveOptions } from '../src/index.ts'
import { deepseekTurn, EXIT_REASON, parseReply, script } from '../src/transport.ts'

// The page evaluates the source; the test does the same, so what is tested is
// exactly the text that is shipped.
function run(prompt: string): Promise<string> {
  const base64 = Buffer.from(prompt, 'utf8').toString('base64')
  // oxlint-disable-next-line typescript/no-implied-eval
  const turn = new Function(`return ${deepseekTurn(base64)}`)() as () => Promise<string>
  return turn()
}

/**
 * A stand-in for a signed-in chat.deepseek.com: a textarea whose React-style
 * listener only sees text that arrived through an `input` event, Enter to send,
 * reasoning streamed into its own panel first, then the answer in pieces.
 */
function mountDeepSeek(answerParts: readonly string[], options: { refuseSend?: boolean } = {}): { sent: string[] } {
  document.body.innerHTML = '<div id="chat"><div class="ds-markdown">an earlier answer</div></div><textarea></textarea>'
  const chat = document.getElementById('chat')!
  const box = document.querySelector('textarea')!
  const sent: string[] = []
  let seen = ''
  box.addEventListener('input', () => { seen = box.value })
  box.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' || options.refuseSend === true) return
    sent.push(seen)
    box.value = ''
    setTimeout(() => {
      chat.insertAdjacentHTML('beforeend', '<div class="ds-think-content"><div class="ds-markdown">thinking...</div></div>')
    }, 50)
    const answer = document.createElement('div')
    answer.className = 'ds-markdown'
    answerParts.forEach((part, i) => {
      setTimeout(() => {
        if (i === 0) chat.append(answer)
        answer.insertAdjacentHTML('beforeend', part)
      }, 400 + i * 300)
    })
  })
  return { sent }
}

afterEach(() => {
  document.body.innerHTML = ''
  window.history.pushState({}, '', '/')
})

describe('deepseekTurn', () => {
  it('sends the decoded prompt and returns only the new answer, not reasoning or history', async () => {
    const page = mountDeepSeek(['<p>Hello ', '<strong>wörld</strong></p>'])
    const reply = await run('say hi — ünïcode\nsecond line')
    expect(page.sent).toEqual(['say hi — ünïcode\nsecond line'])
    expect(reply).toContain('Hello')
    expect(reply).toContain('**wörld**')
    expect(reply).not.toContain('thinking')
    expect(reply).not.toContain('earlier answer')
  }, 15_000)

  it('names a signed-out session instead of waiting for a composer', async () => {
    window.history.pushState({}, '', '/sign_in')
    expect(await run('hi')).toBe('OC_FAIL:23')
  })

  it('fails step 25 when the page refuses the send', async () => {
    mountDeepSeek(['x'], { refuseSend: true })
    expect(await run('hi')).toBe('OC_FAIL:25')
  }, 15_000)
})

describe('deepseek site wiring', () => {
  it('opens chat.deepseek.com and runs the DeepSeek turn, not the ChatGPT one', () => {
    const options = resolveOptions({ site: 'deepseek' })
    expect(options.url).toBe('https://chat.deepseek.com/')
    const text = script(options, Buffer.from('q').toString('base64'))
    expect(text).toContain('open \'https://chat.deepseek.com/\'')
    expect(text).toContain('fail(23)')
    expect(text).not.toContain('data-conversation-role')
  })

  it('keeps ChatGPT the default site', () => {
    const options = resolveOptions({})
    expect(options.site).toBe('chatgpt')
    expect(options.url).toBe('https://chatgpt.com/?temporary-chat=true')
    expect(script(options, 'cQ==')).toContain('data-conversation-role')
  })

  it('refuses an unknown site', () => {
    expect(() => resolveOptions({ site: 'gemini' })).toThrow(/site must be one of chatgpt, deepseek/)
  })

  it('reports a DeepSeek model and names DeepSeek in its errors', async () => {
    const adapter = new OpenClawChatGptAdapter({
      options: () => resolveOptions({ site: 'deepseek' }),
      spawn: () => { throw new Error('unused') },
      displayName: 'DeepSeek (browser, free)',
    })
    const [model] = await adapter.listModels('openclaw-deepseek')
    expect(model?.id).toBe('deepseek-web')
    expect(model?.id).not.toBe(MODEL_ID)
    expect(model?.name).toBe('DeepSeek (browser session)')
  })

  it('surfaces the sign-in failure with its own reason', () => {
    const framed = `x\nOC_REPLY_BEGIN\n${JSON.stringify({ ok: true, result: 'OC_FAIL:23' })}\nOC_REPLY_END\n`
    expect(() => parseReply(framed)).toThrow(EXIT_REASON[23])
  })
})
