  const displayName = text(config.displayName, defaults.displayName)
  const NS = settingsNamespace(`llm-${provider}`)

  let current: () => Config = () => config
  /**
   * Live connection facts for one site, re-resolved when the snapshot changes.
   * @param site - pins the site (and drops the URL) for the unlimited mount.
   */
  const resolver = (site?: Site): (() => OpenClawOptions) => {
    let lastRaw: Config | undefined
    let lastGood: OpenClawOptions | undefined
    return () => {
      const raw = current()
      if (raw === lastRaw && lastGood !== undefined) return lastGood
      try {
        const next = resolveOptions(site === undefined ? raw : { ...raw, site, url: undefined })
        lastRaw = raw
        lastGood = next
        return next
      } catch (error) {
        // Static composition resolves before anything registers, so this branch
        // only sees a live settings snapshot failing a beyond-schema bound: keep
        // serving the last good facts and say so once per bad snapshot.
        if (lastGood === undefined) throw error
        lastRaw = raw
        ctx.logger.error('llm-openclaw-chatgpt: keeping the last good configuration after an invalid settings section')
        ctx.logger.error(error)
        return lastGood
      }
    }
