import type { SubprocessHandle, SubprocessSpawnSpec } from '@deepseek-ai/dsh-subprocess'

function spawn(spec: SubprocessSpawnSpec): SubprocessHandle {
  const [cmd, ...args] = spec.argv
  const child = nodeSpawn(cmd!, args, { cwd: spec.cwd, stdio: ['pipe', 'pipe', 'pipe'] })
  let out = ''
  child.stdout.on('data', (d: Buffer) => { out += d.toString('utf8') })
  child.stderr.on('data', () => {})
  child.stdin.end((spec.stdio?.stdin as { data: string }).data)
  const done = new Promise<{ exitCode: number | null; signal: null }>(r => child.on('close', code => r({ exitCode: code, signal: null })))
  return {
    pid: child.pid ?? 0, stdin: undefined, stdout: undefined, stderr: undefined,
    collected: { stdout: { readFrom: () => ({ text: out, nextOffset: 0, lossy: false }) } },
    done, terminate: () => { child.kill() }, waitForExit: () => done.then(() => true),
  } as unknown as SubprocessHandle
}

