// Chart of accounts (standalone copy for the line-refund module; no prisma import at load).
//   1000 Cash, 1100 Payment Processor Clearing, 2100 Vendor Payable, 4000 Platform Fee Revenue

export const ACCOUNT_CODES = {
  CASH: "1000",
  CLEARING: "1100",
  VENDOR_PAYABLE: "2100",
  PLATFORM_FEE_REVENUE: "4000",
} as const;

export type AccountCode = (typeof ACCOUNT_CODES)[keyof typeof ACCOUNT_CODES];
export type AccountType = "ASSET" | "LIABILITY" | "EQUITY" | "REVENUE" | "EXPENSE";

export interface AccountDef {
  code: AccountCode;
  name: string;
  type: AccountType;
}

export const CHART_OF_ACCOUNTS: readonly AccountDef[] = [
  { code: ACCOUNT_CODES.CASH, name: "Cash", type: "ASSET" },
  { code: ACCOUNT_CODES.CLEARING, name: "Payment Processor Clearing", type: "ASSET" },
  { code: ACCOUNT_CODES.VENDOR_PAYABLE, name: "Vendor Payable", type: "LIABILITY" },
  { code: ACCOUNT_CODES.PLATFORM_FEE_REVENUE, name: "Platform Fee Revenue", type: "REVENUE" },
];

export function normalBalance(type: AccountType): "DEBIT" | "CREDIT" {
  return type === "ASSET" || type === "EXPENSE" ? "DEBIT" : "CREDIT";
}

export function accountDef(code: string): AccountDef | undefined {
  return CHART_OF_ACCOUNTS.find((a) => a.code === code);
}

/** Minimal structural db client (Prisma transaction client in production, fake in tests). */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type LedgerDb = any;

/** Upserts every chart-of-accounts row (by code) and returns code -> id. Idempotent. */
export async function ensureChartOfAccounts(db: LedgerDb, currency = "usd"): Promise<Record<AccountCode, string>> {
  const codes = CHART_OF_ACCOUNTS.map((a) => a.code);
  const existing = await db.account.findMany({ where: { code: { in: codes } }, select: { id: true, code: true } });
  const ids = new Map<string, string>();
  for (const a of existing) if (a.code) ids.set(a.code, a.id);
  for (const def of CHART_OF_ACCOUNTS) {
    if (ids.has(def.code)) continue;
    const row = await db.account.upsert({
      where: { code: def.code },
      update: {},
      create: { code: def.code, name: def.name, type: def.type, currency },
      select: { id: true, code: true },
    });
    ids.set(def.code, row.id);
  }
  return Object.fromEntries(codes.map((c) => [c, ids.get(c)!])) as Record<AccountCode, string>;
}
EOF
