}

/** Throws UnbalancedEntryError unless the lines form a valid balanced entry. Returns the total. */
export function assertBalanced(lines: LedgerLineInput[]): number {
  if (!Array.isArray(lines) || lines.length < 2) throw new UnbalancedEntryError("A journal entry needs at least two lines");
  let debits = 0;
  let credits = 0;
  for (const [i, l] of lines.entries()) {
    for (const [k, v] of [["debit", l.debit], ["credit", l.credit]] as const) {
      if (!Number.isSafeInteger(v) || v < 0) throw new UnbalancedEntryError(`Line ${i}: ${k} must be a non-negative integer (got ${v})`);
    }
    if ((l.debit > 0) === (l.credit > 0)) throw new UnbalancedEntryError(`Line ${i}: exactly one of debit/credit must be > 0`);
    debits += l.debit;
    credits += l.credit;
  }
  if (!Number.isSafeInteger(debits) || !Number.isSafeInteger(credits)) throw new UnbalancedEntryError("Entry total overflows");
  if (debits !== credits) throw new UnbalancedEntryError(`Unbalanced entry: debits ${debits} != credits ${credits}`);
  return debits;
}

export interface PostResult {
  entry: { id: string; sourceKey: string | null; reference: string };
  created: boolean;
}
