// acl.js - Contact Lead ACL, audit and permission gates (T-d0ab1b37, T-d9cf422d).
// Contact grants live in their own table and never overlap Opportunity grants.
import { CONTACT_LEAD } from './schema.js'

export const ACTIONS = Object.freeze(['read', 'create', 'update', 'status', 'dedupe_suggest', 'tag',
  'draft_note', 'link_propose', 'link', 'export', 'email', 'share', 'bulk_delete'])
// External actions always need explicit human approval, whatever the grant.
export const EXTERNAL_ACTIONS = Object.freeze(['export', 'email', 'share', 'bulk_delete'])
// Internal agent actions that may run without repeated approval once granted.
export const INTERNAL_AGENT_ACTIONS = Object.freeze(['read', 'dedupe_suggest', 'tag', 'draft_note', 'link_propose'])

const AUDIT = `${CONTACT_LEAD.table}_audit`

export function migrateAcl(db) {
  db.exec(`CREATE TABLE IF NOT EXISTS contact_acl (
    id INTEGER PRIMARY KEY AUTOINCREMENT, subject TEXT NOT NULL, action TEXT NOT NULL,
    project TEXT NOT NULL DEFAULT '*', granted_by TEXT NOT NULL, at TEXT NOT NULL,
    UNIQUE(subject, action, project))`)
  db.exec(`CREATE TABLE IF NOT EXISTS contact_approvals (
    id INTEGER PRIMARY KEY AUTOINCREMENT, subject TEXT NOT NULL, action TEXT NOT NULL,
    record_id TEXT, status TEXT NOT NULL DEFAULT 'pending', requested_at TEXT NOT NULL,
    decided_by TEXT, decided_at TEXT)`)
}

export function audit(db, { recordId, action, actor, model = null, before = null, after = null, detail = {} }) {
  if (!actor) throw new Error('audit needs an actor')
  db.prepare(`INSERT INTO ${AUDIT} (record_id, record_type, action, actor, model, at, before, after, detail)
    VALUES (?,?,?,?,?,?,?,?,?)`).run(recordId, CONTACT_LEAD.type, action, actor, model,
    new Date().toISOString(), before === null ? null : JSON.stringify(before),
    after === null ? null : JSON.stringify(after), JSON.stringify(detail))
}
export function auditTrail(db, recordId) {
  return db.prepare(`SELECT * FROM ${AUDIT} WHERE record_id = ? ORDER BY seq`).all(recordId)
}

export function grant(db, { subject, action, project = '*', grantedBy }) {
  if (!ACTIONS.includes(action)) throw new Error(`unknown action ${action}`)
  db.prepare('INSERT OR IGNORE INTO contact_acl (subject, action, project, granted_by, at) VALUES (?,?,?,?,?)')
    .run(subject, action, project, grantedBy, new Date().toISOString())
}
export function revoke(db, { subject, action, project = '*' }) {
  db.prepare('DELETE FROM contact_acl WHERE subject=? AND action=? AND project=?').run(subject, action, project)
}
export function hasGrant(db, subject, action, project = '*') {
  return Boolean(db.prepare(`SELECT 1 FROM contact_acl WHERE subject=? AND action=?
    AND (project=? OR project='*')`).get(subject, action, project))
}

/**
 * Gate check. Returns { allow, reason, approvalId? }.
 * Only contact_acl is consulted: an Opportunity grant is a different store and opens nothing here.
 * External actions are blocked until a human approval for that exact subject/action/record exists.
 */
export function check(db, { subject, action, project = '*', recordId = null, kind = 'agent' }) {
  if (!ACTIONS.includes(action)) return { allow: false, reason: 'unknown action' }
  if (!hasGrant(db, subject, action, project)) return { allow: false, reason: 'no contact grant' }
  if (EXTERNAL_ACTIONS.includes(action)) {
    const ok = db.prepare(`SELECT id FROM contact_approvals WHERE subject=? AND action=? AND status='approved'
      AND COALESCE(record_id,'')=COALESCE(?,'') ORDER BY id DESC LIMIT 1`).get(subject, action, recordId)
    if (ok) return { allow: true, reason: 'human approved', approvalId: ok.id }
    const pending = requestApproval(db, { subject, action, recordId })
    return { allow: false, reason: 'human approval required', approvalId: pending }
  }
  if (kind === 'agent' && !INTERNAL_AGENT_ACTIONS.includes(action)) {
    return { allow: false, reason: 'agent may not perform this internal action' }
  }
  return { allow: true, reason: 'granted' }
}
export function requestApproval(db, { subject, action, recordId = null }) {
  const dup = db.prepare(`SELECT id FROM contact_approvals WHERE subject=? AND action=? AND status='pending'
    AND COALESCE(record_id,'')=COALESCE(?,'')`).get(subject, action, recordId)
  if (dup) return dup.id
  return Number(db.prepare('INSERT INTO contact_approvals (subject, action, record_id, requested_at) VALUES (?,?,?,?)')
    .run(subject, action, recordId, new Date().toISOString()).lastInsertRowid)
}
export function decide(db, approvalId, { approve, decidedBy }) {
  if (!decidedBy || /^(agent|bot|system)/i.test(decidedBy)) throw new Error('approval needs a human decider')
  db.prepare('UPDATE contact_approvals SET status=?, decided_by=?, decided_at=? WHERE id=? AND status=\'pending\'')
    .run(approve ? 'approved' : 'rejected', decidedBy, new Date().toISOString(), approvalId)
}
export function pendingApprovals(db) {
  return db.prepare("SELECT * FROM contact_approvals WHERE status='pending' ORDER BY id").all()
}
