    reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
    UNIQUE(contact_id, opportunity_id))`)
  db.exec(`CREATE TABLE IF NOT EXISTS ${OPP_AUDIT} (
    seq INTEGER PRIMARY KEY AUTOINCREMENT, opportunity_id TEXT NOT NULL, action TEXT NOT NULL,
    actor TEXT NOT NULL, at TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '{}')`)
}

export function addLink(db, { contactId, opportunityId, reason, actor, model = null }) {
  if (!/^CL-[0-9a-f]+$/.test(contactId ?? '')) throw new Error('contactId must be CL-<hex>')
  if (!/^OPP-[0-9a-f]+$/i.test(opportunityId ?? '')) throw new Error('opportunityId must be OPP-<hex>')
  if (!reason || !String(reason).trim()) throw new Error('link reason required')
  if (!actor) throw new Error('creator required')
  const at = new Date().toISOString()
  db.prepare('INSERT INTO contact_opportunity_links (contact_id, opportunity_id, reason, created_by, created_at) VALUES (?,?,?,?,?)')
    .run(contactId, opportunityId, reason.trim(), actor, at)
  audit(db, { recordId: contactId, action: 'link_add', actor, model, detail: { opportunityId, reason } })
  db.prepare(`INSERT INTO ${OPP_AUDIT} (opportunity_id, action, actor, at, detail) VALUES (?,?,?,?,?)`)
    .run(opportunityId, 'link_add', actor, at, JSON.stringify({ contactId, reason }))
}
export function removeLink(db, { contactId, opportunityId, actor, model = null }) {
  const r = db.prepare('DELETE FROM contact_opportunity_links WHERE contact_id=? AND opportunity_id=?').run(contactId, opportunityId)
  if (!r.changes) return false
  audit(db, { recordId: contactId, action: 'link_remove', actor, model, detail: { opportunityId } })
  db.prepare(`INSERT INTO ${OPP_AUDIT} (opportunity_id, action, actor, at, detail) VALUES (?,?,?,?,?)`)
    .run(opportunityId, 'link_remove', actor, new Date().toISOString(), JSON.stringify({ contactId }))
  return true
}
export const linksForContact = (db, id) =>
  db.prepare('SELECT * FROM contact_opportunity_links WHERE contact_id=? ORDER BY id').all(id)
export const linksForOpportunity = (db, id) =>
  db.prepare('SELECT * FROM contact_opportunity_links WHERE opportunity_id=? ORDER BY id').all(id)
export const opportunityAudit = (db, id) =>
  db.prepare(`SELECT * FROM ${OPP_AUDIT} WHERE opportunity_id=? ORDER BY seq`).all(id)

const CONVERSION_OPS = /^(convert|promote|copy_as|copy-as|copyas|transform|migrate|to_opportunity|to_contact)/i
/** Guard: every conversion-style operation, in either direction, is rejected. */
export function guardOperation(op, { from, to } = {}) {
  if (CONVERSION_OPS.test(op ?? '')) throw new ConversionRejected(`operation "${op}" rejected: links are references only`)
  if (from && to && from !== to) throw new ConversionRejected(`cross-type ${from} -> ${to} rejected`)
  return true
}
