// Lead Qualification (Blitz L7): score and qualify Opportunity records.
//
// Eligibility rules, fit scoring, deadline/budget filters, duplicate
// detection and evidence capture. Results flow into a Pending Review queue
// with the evidence attached. Operates on Opportunity records ONLY: it never
// creates or converts to a Contact Lead (no contact fields are read or written).
'use strict';

const { dedupe } = require('./dedup');

const DAY = 86400000;

/** Parse "$1,200,000", "500k", "2.5M", "EUR 40 000" to a number, or null. */
function parseValue(value) {
  if (value === null || value === undefined) return null;
  const text = String(value).toLowerCase().replace(/,/g, '').replace(/(?<=\d)\s(?=\d{3}\b)/g, '');
  const m = text.match(/(\d+(?:\.\d+)?)\s*(k|m|b|million|billion|thousand)?/);
  if (!m) return null;
  const mult = { k: 1e3, thousand: 1e3, m: 1e6, million: 1e6, b: 1e9, billion: 1e9 }[m[2]] || 1;
  return Math.round(parseFloat(m[1]) * mult);
}

function haystack(r) {
  return [r.title, r.description, ...(r.tags || [])].join(' ').toLowerCase();
}

function evidence(rule, passed, detail) {
  return { rule, passed, detail };
}

/**
 * Qualify one opportunity.
 * profile: { keywords, excludeKeywords, categories, agencies, locations,
 *            minValue, maxValue, minDaysToClose, minScore, now }
 */
function qualify(record, profile = {}) {
  const now = profile.now ? new Date(profile.now).getTime() : Date.now();
  const ev = [];
  const reasons = [];
  let score = 0;

  // Eligibility: hard rules.
  const close = Date.parse(record.closingDate);
  const days = Number.isNaN(close) ? null : (close - now) / DAY;
  const minDays = profile.minDaysToClose ?? 3;
  if (days === null) {
    ev.push(evidence('deadline', false, 'closingDate unparseable'));
    reasons.push('invalid deadline');
  } else if (days < 0) {
    ev.push(evidence('deadline', false, `closed ${Math.abs(Math.round(days))}d ago`));
    reasons.push('expired');
  } else if (days < minDays) {
    ev.push(evidence('deadline', false, `closes in ${days.toFixed(1)}d, need >= ${minDays}d`));
    reasons.push('deadline too close');
  } else {
    ev.push(evidence('deadline', true, `closes in ${Math.round(days)}d`));
    score += days <= 30 ? 10 : 15;
  }

  const val = parseValue(record.value);
  if (val !== null) {
    const { minValue, maxValue } = profile;
    if (minValue != null && val < minValue) {
      ev.push(evidence('budget', false, `value ${val} < min ${minValue}`));
      reasons.push('below budget');
    } else if (maxValue != null && val > maxValue) {
      ev.push(evidence('budget', false, `value ${val} > max ${maxValue}`));
      reasons.push('above budget');
    } else {
      ev.push(evidence('budget', true, `value ${val} in range`));
      score += 20;
    }
  } else {
    ev.push(evidence('budget', true, 'value unknown; not filtered'));
  }

  const text = haystack(record);
  const excl = (profile.excludeKeywords || []).filter((k) => text.includes(k.toLowerCase()));
  if (excl.length) {
    ev.push(evidence('exclusions', false, `matched: ${excl.join(', ')}`));
    reasons.push('excluded keyword');
  }

  if (profile.categories && profile.categories.length && !profile.categories.includes(record.category)) {
    ev.push(evidence('category', false, `${record.category || 'none'} not in ${profile.categories.join('/')}`));
    reasons.push('category not eligible');
  } else if (profile.categories && profile.categories.length) {
    ev.push(evidence('category', true, record.category));
    score += 10;
  }

  // Fit scoring.
  const kws = profile.keywords || [];
  if (kws.length) {
    const hit = kws.filter((k) => text.includes(k.toLowerCase()));
    const pts = Math.round((hit.length / kws.length) * 40);
    ev.push(evidence('keywords', hit.length > 0, hit.length ? `matched ${hit.join(', ')}` : 'no keyword match'));
    score += pts;
  }
  if (profile.agencies && profile.agencies.length) {
    const ok = profile.agencies.some((a) => (record.agency || '').toLowerCase().includes(a.toLowerCase()));
    ev.push(evidence('agency', ok, record.agency || 'unknown'));
    if (ok) score += 10;
  }
  if (profile.locations && profile.locations.length) {
    const ok = profile.locations.some((l) => (record.location || '').toLowerCase().includes(l.toLowerCase()));
    ev.push(evidence('location', ok, record.location || 'unknown'));
    if (ok) score += 5;
  }

  score = Math.min(100, score);
  const minScore = profile.minScore ?? 40;
  if (!reasons.length && score < minScore) reasons.push(`score ${score} < ${minScore}`);
  const verdict = reasons.length ? 'rejected' : 'qualified';
  return { opportunityId: record.id, verdict, score, reasons, evidence: ev, evaluatedAt: new Date(now).toISOString() };
}

/** Pending Review queue: every result waits for a human decision. */
class PendingReview {
  constructor() {
    this.items = new Map();
  }
  add(record, result) {
    const item = { opportunityId: record.id, record, result, status: 'pending', decidedBy: null, decidedAt: null };
    this.items.set(record.id, item);
    return item;
  }
  list(status = 'pending') {
    return [...this.items.values()].filter((i) => !status || i.status === status);
  }
  decide(id, decision, actor) {
    const item = this.items.get(id);
    if (!item) throw new Error(`no pending item ${id}`);
    if (!['approved', 'rejected'].includes(decision)) throw new Error('decision must be approved or rejected');
    if (!actor) throw new Error('actor required');
    item.status = decision;
    item.decidedBy = actor;
    item.decidedAt = new Date().toISOString();
    return item;
  }
}

/** Dedup, qualify, and enqueue a batch. Duplicates are recorded as evidence. */
function qualifyBatch(records, profile = {}, queue = new PendingReview()) {
  const { records: unique, duplicates } = dedupe(records, { crossSource: profile.crossSource !== false });
  const dupIds = new Map();
  for (const d of duplicates) for (const id of d.mergedIds) if (id !== d.keptId) dupIds.set(d.keptId, [...(dupIds.get(d.keptId) || []), id]);
  const results = unique.map((rec) => {
    const result = qualify(rec, profile);
    const merged = dupIds.get(rec.id);
    if (merged) result.evidence.push(evidence('duplicates', true, `merged ${merged.join(', ')}`));
    queue.add(rec, result);
    return result;
  });
  return { results, duplicates, queue };
}

module.exports = { parseValue, qualify, qualifyBatch, PendingReview };
