/** Dated, SKU-level, event-scoped wholesale price list. */
const PriceListEntry = (i) => make('PriceListEntry', {
  sku: [isStr, 'required'], unitCents: [int0, 'must be integer cents >= 0'],
});
const Agreement = (i) => {
  const rec = make('Agreement', {
    id: [isStr, 'required'], brandId: [isStr, 'required'], eventId: [opt(isStr), 'must be string'],
    effectiveFrom: [isDate, 'must be ISO date'],
    effectiveTo: [opt((v, r) => isDate(v) && Date.parse(v) >= Date.parse(r.effectiveFrom)), 'must be ISO date >= effectiveFrom'],
    prices: [(v) => Array.isArray(v) && v.length > 0, 'needs price entries'],
  }, i);
  rec.prices.forEach(PriceListEntry);
  const skus = rec.prices.map((p) => p.sku);
  if (new Set(skus).size !== skus.length) throw new ValidationError('Agreement', ['prices has duplicate SKU']);
  return rec;
};
/** Price for sku at a date, honouring event scope; null if none. */
function priceFor(agreements, { brandId, sku, date, eventId }) {
  const t = Date.parse(date);
  const hits = agreements.filter((a) => a.brandId === brandId
    && Date.parse(a.effectiveFrom) <= t && (!a.effectiveTo || t <= Date.parse(a.effectiveTo))
    && (!a.eventId || a.eventId === eventId));
  hits.sort((a, b) => (b.eventId ? 1 : 0) - (a.eventId ? 1 : 0) || Date.parse(b.effectiveFrom) - Date.parse(a.effectiveFrom));
  for (const a of hits) { const p = a.prices.find((x) => x.sku === sku); if (p) return p.unitCents; }
  return null;
}

const FeeModel = (i) => make('FeeModel', {
  id: [isStr, 'required'], eventId: [isStr, 'required'], feeType: [isStr, 'required'],
  percentBp: [opt(int0), 'must be basis points integer'], flatCents: [opt(int0), 'must be integer cents'],
}, i, { percentBp: 0, flatCents: 0 });

const Invoice = (i) => make('Invoice', {
  id: [isStr, 'required'], eventId: [isStr, 'required'], payerId: [isStr, 'required'],
  lines: [(v) => Array.isArray(v) && v.length > 0 && v.every((l) => isStr(l.description) && int0(l.cents)), 'needs lines {description, cents}'],
  taxBp: [opt(int0), 'must be basis points integer'],
}, i, { taxBp: 0 });
function invoiceTotals(inv) {
  const subtotal = inv.lines.reduce((s, l) => s + l.cents, 0);
  const tax = Math.round((subtotal * inv.taxBp) / 10000);
  return { subtotalCents: subtotal, taxCents: tax, totalCents: subtotal + tax };
}

const ProcessorEligibility = (i) => {
  const rec = make('ProcessorEligibility', {
    processor: [isStr, 'required'], feeType: [isStr, 'required'],
    eventType: [oneOf(EVENT_KINDS), 'invalid event type'], jurisdiction: [isStr, 'required'],
    status: [oneOf(ELIGIBILITY_STATUS), 'must be approved|pending|unsupported'],
    evidence: [opt(isStr), 'must be string'], approver: [opt(isStr), 'must be string'],
  }, i);
  if (rec.status === 'approved' && !(isStr(rec.evidence) && isStr(rec.approver))) {
    throw new ValidationError('ProcessorEligibility', ['approved requires evidence and approver']);
  }
  return rec;
};
/** Only an exact approved row permits processing; pending/unsupported/missing all deny. */
function isProcessorAllowed(rows, { processor, feeType, eventType, jurisdiction }) {
  return rows.some((r) => r.processor === processor && r.feeType === feeType
    && r.eventType === eventType && r.jurisdiction === jurisdiction && r.status === 'approved');
}

/** Role permissions (deny by default). */
const PERMISSIONS = Object.freeze({
  admin: ['*'],
  organizer: ['event:write', 'booth:allocate', 'ticket:write', 'staff:schedule', 'brand:invite'],
  brand: ['booth:read', 'lead:capture', 'agreement:read'],
  staff: ['shift:read', 'badge:scan'],
  attendee: ['ticket:buy'],
});
const can = (role, perm) => { const p = PERMISSIONS[role]; return !!p && (p.includes('*') || p.includes(perm)); };

/** Compliance/payment gate: event may open sales only if every gate passes. Returns {ok, failures}. */
function checkGates({ event, eligibility = [], processor, feeType, licenseVerified }) {
  const failures = [];
  if (!isProcessorAllowed(eligibility, { processor, feeType, eventType: event.type, jurisdiction: event.jurisdiction })) failures.push('processor not approved');
  if (!licenseVerified) failures.push('license not verified');
  return { ok: failures.length === 0, failures };
}

/** Audit entry (append-only log record). */
const AuditEntry = (i) => make('AuditEntry', {
  actor: [isStr, 'required'], action: [isStr, 'required'], entity: [isStr, 'required'], entityId: [isStr, 'required'],
  at: [isDate, 'must be ISO date'],
});

module.exports = {
  EVENT_KINDS, ELIGIBILITY_STATUS, ROLES, SCHEMA_OWNERS, PERMISSIONS, ValidationError,
  Event, Booth, Ticket, Badge, Organizer, StaffShift, Equipment, Brand, Location,
  PriceListEntry, Agreement, priceFor, FeeModel, Invoice, invoiceTotals,
  ProcessorEligibility, isProcessorAllowed, can, checkGates, AuditEntry,
};
