"""Offline NSRDB weather cache. Key = dataset/grid/version/content-hash. Never makes network calls."""
import hashlib, json, os, shutil

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()

def cache_key(dataset, grid, version, content_hash):
    for n, v in (("dataset", dataset), ("grid", grid), ("version", version), ("content_hash", content_hash)):
        if not v or not isinstance(v, str) or "/" in v or "\\" in v or ".." in v:
            raise ValueError("invalid cache key part: " + n)
    return "/".join((dataset, grid, version, content_hash))

class WeatherCache:
    def __init__(self, root):
        self.root = root

    def _dir(self, key):
        return os.path.join(self.root, *key.split("/"))

    def put(self, dataset, grid, version, src_path):
        """Store a file; the content hash is computed, never trusted from the caller."""
        h = sha256_file(src_path)
        key = cache_key(dataset, grid, version, h)
        d = self._dir(key)
        os.makedirs(d, exist_ok=True)
        dest = os.path.join(d, "weather.csv")
        if not os.path.exists(dest):
            shutil.copyfile(src_path, dest)
        with open(os.path.join(d, "meta.json"), "w") as f:
            json.dump({"key": key, "sha256": h, "dataset": dataset, "grid": grid, "version": version}, f)
        return key, dest

    def get(self, dataset, grid, version, content_hash):
        """Return path or None. Re-verifies content hash so corrupt entries are misses."""
        key = cache_key(dataset, grid, version, content_hash)
        p = os.path.join(self._dir(key), "weather.csv")
        if os.path.isfile(p) and sha256_file(p) == content_hash:
            return p
        return None
