"""Pinned CEC module/inverter library references + electrical compatibility check."""
import hashlib

# Pins are placeholders until the CSVs are vendored on ndi2; verify_pin fails closed on mismatch.
CEC_PINS = {
    "module": {"file": "CEC Modules.csv", "release_tag": "SAM-2026.7.3", "commit": None, "sha256": None},
    "inverter": {"file": "CEC Inverters.csv", "release_tag": "SAM-2026.7.3", "commit": None, "sha256": None},
}

def verify_pin(kind, path, pins=None):
    pin = (pins or CEC_PINS)[kind]
    if not pin.get("sha256"):
        raise ValueError("CEC %s pin has no sha256: unpinned library refused" % kind)
    h = hashlib.sha256(open(path, "rb").read()).hexdigest()
    if h != pin["sha256"]:
        raise ValueError("CEC %s hash mismatch: %s != %s" % (kind, h, pin["sha256"]))
    return {"kind": kind, "release_tag": pin["release_tag"], "commit": pin.get("commit"), "sha256": h}

def check_compatibility(module, inverter, n_series, n_parallel=1):
    """module: {id, vmp, voc, imp}; inverter: {id, vdcmax, mppt_low, mppt_high, idcmax, paco}.
    Returns list of problems (empty = compatible)."""
    p = []
    vmp, voc, imp = module["vmp"] * n_series, module["voc"] * n_series, module["imp"] * n_parallel
    if voc > inverter["vdcmax"]: p.append("string Voc %.1f V exceeds inverter Vdcmax %.1f V" % (voc, inverter["vdcmax"]))
    if not inverter["mppt_low"] <= vmp <= inverter["mppt_high"]:
        p.append("string Vmp %.1f V outside MPPT window %.1f-%.1f V" % (vmp, inverter["mppt_low"], inverter["mppt_high"]))
    if imp > inverter["idcmax"]: p.append("array Imp %.1f A exceeds inverter Idcmax %.1f A" % (imp, inverter["idcmax"]))
    return p
