cat > sam_worker.py <<'EOF'
"""SAM PySAM CLI worker. JSON on stdin, JSON on stdout. Failure never emits ok:true.

Request: {correlation_id?, model: pvwattsv8|pvsamv1, location:{lat,lon},
          system:{...model inputs...}, weather:{tmy:path, years:[{year:int,path:str}]},
          config?:{Group:{var:val}} (SAM Desktop export overrides), timeout_s?:number}
Exit codes: 0 ok, 2 error. Stdout always one JSON object.
"""
import hashlib, json, os, platform, sys, threading, uuid

SCHEMA = "sam_worker/1"
MODELS = ("pvwattsv8", "pvsamv1")
DEFAULT_TIMEOUT = 120.0
MAX_TIMEOUT = 900.0

class WorkerError(Exception):
    def __init__(self, code, message, field=None):
        super().__init__(message)
        self.code, self.field = code, field

def fingerprint(req):
    body = {k: v for k, v in req.items() if k not in ("correlation_id", "timeout_s")}
    return hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":")).encode()).hexdigest()

def validate(req):
    if not isinstance(req, dict): raise WorkerError("INVALID_INPUT", "request must be an object")
    if req.get("model") not in MODELS:
        raise WorkerError("INVALID_INPUT", "model must be one of %s" % (MODELS,), "model")
    loc = req.get("location")
    if not isinstance(loc, dict) or not all(isinstance(loc.get(k), (int, float)) and not isinstance(loc.get(k), bool) for k in ("lat", "lon")):
        raise WorkerError("INVALID_INPUT", "location.lat/lon numeric required", "location")
    if not -90 <= loc["lat"] <= 90 or not -180 <= loc["lon"] <= 180:
        raise WorkerError("INVALID_INPUT", "location out of range", "location")
    if not isinstance(req.get("system"), dict) or not req["system"]:
        raise WorkerError("INVALID_INPUT", "system object required", "system")
    cap = req["system"].get("system_capacity")
    if req["model"] == "pvwattsv8" and not (isinstance(cap, (int, float)) and not isinstance(cap, bool) and cap > 0):
        raise WorkerError("INVALID_INPUT", "system.system_capacity > 0 required", "system.system_capacity")
    w = req.get("weather")
    if not isinstance(w, dict) or not isinstance(w.get("tmy"), str):
        raise WorkerError("INVALID_INPUT", "weather.tmy path required (TMY baseline)", "weather.tmy")
    years = w.get("years", [])
    if not isinstance(years, list) or any(not isinstance(y, dict) or not isinstance(y.get("year"), int) or not isinstance(y.get("path"), str) for y in years):
        raise WorkerError("INVALID_INPUT", "weather.years must be [{year:int,path:str}]", "weather.years")
    if len({y["year"] for y in years}) != len(years):
        raise WorkerError("INVALID_INPUT", "duplicate weather year", "weather.years")
    for p in [w["tmy"]] + [y["path"] for y in years]:
        if not os.path.isfile(p): raise WorkerError("WEATHER_MISSING", "weather file not found: " + p, "weather")
    if "config" in req and not isinstance(req["config"], dict):
        raise WorkerError("INVALID_INPUT", "config must be an object", "config")
    t = req.get("timeout_s", DEFAULT_TIMEOUT)
    if not isinstance(t, (int, float)) or isinstance(t, bool) or not 0 < t <= MAX_TIMEOUT:
        raise WorkerError("INVALID_INPUT", "timeout_s must be in (0,%s]" % MAX_TIMEOUT, "timeout_s")

def versions():
    v = {"worker": SCHEMA, "python": platform.python_version()}
    try:
        import PySAM
        v["pysam"] = getattr(PySAM, "__version__", None) or "unknown"
        try:
            import PySAM.PySSC as ssc
            v["ssc"] = str(ssc.default_ssc_instance().version()) if hasattr(ssc, "default_ssc_instance") else "unknown"
        except Exception:
            v["ssc"] = "unknown"
    except ImportError:
        v["pysam"] = None
    return v

def pysam_runner(req, weather_path):
    """Run Pvwattsv8 or Pvsamv1 then Grid on one weather file. Returns {annual_kwh, monthly_kwh}."""
    try:
        import PySAM.Pvwattsv8 as PVW, PySAM.Pvsamv1 as PVS, PySAM.Grid as GRID
    except ImportError as e:
        raise WorkerError("PYSAM_UNAVAILABLE", "PySAM not importable: %s" % e)
    if req["model"] == "pvwattsv8":
        m = PVW.default("PVWattsNone")
    else:
        m = PVS.default("FlatPlatePVNone")
    loc = req["location"]
    try:
        m.assign({"SolarResource": {"solar_resource_file": weather_path}})
        m.assign({"SystemDesign" if req["model"] == "pvwattsv8" else "System": req["system"]} if False else {})
        m.assign({"SystemDesign": req["system"]} if req["model"] == "pvwattsv8" else {"SystemDesign": req["system"]})
        for grp, vals in req.get("config", {}).items():
            m.assign({grp: vals})
        m.execute()
        g = GRID.from_existing(m, "PVWattsNone" if req["model"] == "pvwattsv8" else "FlatPlatePVNone")
        g.execute()
        monthly = list(g.Outputs.monthly_energy) if hasattr(g.Outputs, "monthly_energy") else list(m.Outputs.monthly_energy)
        annual = float(g.Outputs.annual_energy) if hasattr(g.Outputs, "annual_energy") else float(m.Outputs.annual_energy)
    except WorkerError:
        raise
    except Exception as e:
        raise WorkerError("MODEL_FAILED", "%s failed: %s" % (req["model"], e))
    if not annual > 0 or len(monthly) != 12:
        raise WorkerError("MODEL_FAILED", "model produced invalid output")
    return {"annual_kwh": annual, "monthly_kwh": monthly}

def compute(req, runner=pysam_runner):
    w = req["weather"]
    tmy = runner(req, w["tmy"])
    years = [dict(year=y["year"], **runner(req, y["path"])) for y in sorted(w.get("years", []), key=lambda y: y["year"])]
    out = {"tmy": tmy, "years": years}
    if years:  # low/high reported separately, never blended into TMY
        lo = min(years, key=lambda y: y["annual_kwh"]); hi = max(years, key=lambda y: y["annual_kwh"])
        out["low"] = {"year": lo["year"], "annual_kwh": lo["annual_kwh"]}
        out["high"] = {"year": hi["year"], "annual_kwh": hi["annual_kwh"]}
    return out

def handle(raw, runner=pysam_runner):
    """Pure entry: raw JSON string -> (response dict, exit code). Never raises."""
    cid = None
    try:
        try:
            req = json.loads(raw)
        except ValueError as e:
            raise WorkerError("INVALID_JSON", str(e))
        if isinstance(req, dict):
            cid = req.get("correlation_id")
        cid = cid if isinstance(cid, str) and cid else str(uuid.uuid4())
        validate(req)
        base = {"schema": SCHEMA, "correlation_id": cid, "input_fingerprint": fingerprint(req), "versions": versions()}
        box = {}
        def run():
            try: box["r"] = compute(req, runner)
            except BaseException as e: box["e"] = e
        t = threading.Thread(target=run, daemon=True)
        t.start(); t.join(req.get("timeout_s", DEFAULT_TIMEOUT))
        if t.is_alive(): raise WorkerError("TIMEOUT", "exceeded %ss" % req.get("timeout_s", DEFAULT_TIMEOUT))
        if "e" in box:
            e = box["e"]
            if isinstance(e, WorkerError): raise e
            raise WorkerError("INTERNAL", "%s: %s" % (type(e).__name__, e))
        return dict(base, ok=True, model=req["model"], results=box["r"]), 0
    except WorkerError as e:
        resp = {"schema": SCHEMA, "ok": False, "correlation_id": cid or str(uuid.uuid4()),
                "error": {"code": e.code, "message": str(e), "field": e.field}, "versions": versions()}
        return resp, 2

def main():
    resp, code = handle(sys.stdin.read())
    sys.stdout.write(json.dumps(resp)); sys.stdout.flush()
    os._exit(code)  # also kills any timed-out daemon thread

if __name__ == "__main__":
    main()
