import { test } from "node:test";
import assert from "node:assert/strict";
import { getErpDriver } from "../src/drivers/erp.ts";
import { getPosDriver } from "../src/drivers/pos.ts";

const vault = (m: Record<string, string>) => ({ get: async (k: string) => m[k] }) as any;

type Rec = { url: string; method?: string; headers?: Record<string, string>; body?: string };
function replay(routes: Record<string, { status?: number; body: unknown }>) {
  const calls: Rec[] = [];
  const f = async (url: string, init?: any) => {
    calls.push({ url, ...init });
    const r = routes[`${init?.method ?? "GET"} ${url}`];
    if (!r) return { ok: false, status: 404, json: async () => ({}) };
    const status = r.status ?? 200;
    return { ok: status < 400, status, json: async () => r.body };
  };
  return { f, calls };
}

const order = { id: "o1", vendorOrderRef: "PO-9", totalCents: 5000, lines: [{ sku: "A", quantity: 2, unitPriceCents: 2500 }] };

test("ERP sandbox without credentials makes no HTTP call", async () => {
  const { f, calls } = replay({});
  for (const k of ["distru", "leaflink"] as const) {
