  vendorId: string | null;
  note: string | null;
  createdAt: Date;
}

export interface BackfillOrder {
  orderId: string;
  at: Date;
  lines: LedgerLineInput[];
}

export interface BackfillPlan {
  orders: BackfillOrder[];
  unparseable: string[]; // HouseRevenue ids whose note does not name an order
}

/** Pure: group ORDER_SALE rows by order and build balanced lines per order. */
export function planBackfill(rows: HouseRevenueRow[]): BackfillPlan {
  const byOrder = new Map<string, HouseRevenueRow[]>();
  const unparseable: string[] = [];
  for (const r of rows) {
    const m = r.note ? NOTE_RE.exec(r.note.trim()) : null;
    if (!m || !r.vendorId) {
      unparseable.push(r.id);
      continue;
    }
    byOrder.set(m[1], [...(byOrder.get(m[1]) ?? []), r]);
  }
  const orders: BackfillOrder[] = [];
  for (const [orderId, rs] of byOrder) {
    const lines: LedgerLineInput[] = [];
    let gross = 0;
    for (const r of rs) {
      if (r.grossAmountMinor <= 0 || r.amountMinor < 0 || r.amountMinor > r.grossAmountMinor) {
        unparseable.push(r.id);
        continue;
      }
      const net = r.grossAmountMinor - r.amountMinor;
      gross += r.grossAmountMinor;
      if (net > 0) lines.push({ accountCode: ACCOUNT_CODES.VENDOR_PAYABLE, debit: 0, credit: net, vendorId: r.vendorId, description: `Vendor ${r.vendorId} net (backfill)` });
      if (r.amountMinor > 0) lines.push({ accountCode: ACCOUNT_CODES.PLATFORM_FEE_REVENUE, debit: 0, credit: r.amountMinor, vendorId: r.vendorId, description: `Platform fee on vendor ${r.vendorId} (backfill)` });
    }
    if (gross === 0) continue;
    lines.unshift({ accountCode: ACCOUNT_CODES.CLEARING, debit: gross, credit: 0, description: "Captured buyer payment (backfill)" });
    const at = rs.reduce((d, r) => (r.createdAt > d ? r.createdAt : d), rs[0].createdAt);
    orders.push({ orderId, at, lines });
  }
  return { orders, unparseable };
}

export interface BackfillResult {
  candidates: number;
  posted: number;
  skippedExisting: number;
  unparseable: string[];
  dryRun: boolean;
}

export async function backfillLedger(db: LedgerDb, opts: { dryRun?: boolean } = {}): Promise<BackfillResult> {
  const rows = (await db.houseRevenue.findMany({ where: { source: "ORDER_SALE" } })) as HouseRevenueRow[];
  const plan = planBackfill(rows);
  const ids = plan.orders.map((o) => o.orderId);
  const existing = ids.length
    ? await db.journalEntry.findMany({ where: { reference: { in: ids } }, select: { reference: true, sourceKey: true } })
    : [];
  const covered = new Set(existing.filter((e: any) => typeof e.sourceKey === "string" && e.sourceKey.startsWith("payment:")).map((e: any) => e.reference));
  let posted = 0;
  let skippedExisting = 0;
  for (const o of plan.orders) {
    if (covered.has(o.orderId)) {
      skippedExisting++;
      continue;
    }
    if (opts.dryRun) {
      posted++;
      continue;
    }
    const res = await postJournalEntry(db, {
      sourceKey: backfillSourceKey(o.orderId),
      reference: o.orderId,
      description: `Backfill of pre-ledger order ${o.orderId}`,
      entryDate: o.at,
      lines: o.lines,
    });
    if (res.created) posted++;
    else skippedExisting++;
  }
  return { candidates: plan.orders.length, posted, skippedExisting, unparseable: plan.unparseable, dryRun: !!opts.dryRun };
}

export interface BookCheck {
  debitMinor: number;
  creditMinor: number;
  balanced: boolean;
  unbalancedEntries: string[];
}

/** Verifies debits == credits over the whole book and per entry. */
export async function verifyBook(db: LedgerDb): Promise<BookCheck> {
  const lines = (await db.journalEntryLine.findMany({ select: { journalEntryId: true, debit: true, credit: true } })) as Array<{ journalEntryId: string; debit: number; credit: number }>;
  let debitMinor = 0;
  let creditMinor = 0;
  const per = new Map<string, number>();
  for (const l of lines) {
    debitMinor += l.debit;
    creditMinor += l.credit;
    per.set(l.journalEntryId, (per.get(l.journalEntryId) ?? 0) + l.debit - l.credit);
  }
  const unbalancedEntries = [...per].filter(([, d]) => d !== 0).map(([id]) => id);
  return { debitMinor, creditMinor, balanced: debitMinor === creditMinor && unbalancedEntries.length === 0, unbalancedEntries };
}
