// Admin credential rotation over the single vault (src/lib/vault.ts).
// Secrets are encrypted before they reach the store; list output is masked and
// never contains plaintext or ciphertext. Store is injected so tests need no DB.

import { CredentialVault, decryptSecret, encryptSecret, VaultError } from "./vault.ts";

export type CredentialScope = { kind: "setting"; vendorId: string; key: string } | { kind: "driver"; vendorId: string; driver: string };

export interface CredentialRow {
  scope: CredentialScope;
  ciphertext: string;
  updatedAt: Date;
}

export interface CredentialStore {
  put(scope: CredentialScope, ciphertext: string, at: Date): Promise<void>;
  get(scope: CredentialScope): Promise<string | undefined>;
  list(vendorId?: string): Promise<CredentialRow[]>;
}

export interface MaskedCredential {
  scope: CredentialScope;
  masked: string;
  updatedAt: string;
}

/** Last-4 mask; short secrets are fully hidden. */
export function maskSecret(plain: string): string {
  return plain.length > 8 ? `${"*".repeat(8)}${plain.slice(-4)}` : "*".repeat(8);
}

export interface VaultAdminDeps {
  store: CredentialStore;
  masterKey: string;
  vault?: CredentialVault;
  now?: () => Date;
}

export function createVaultAdmin(deps: VaultAdminDeps) {
  const now = deps.now ?? (() => new Date());
  const keyOf = (s: CredentialScope) => (s.kind === "setting" ? `${s.vendorId}:${s.key}` : `${s.vendorId}:driver:${s.driver}`);
  if (!deps.masterKey) throw new VaultError("vault_no_key", "INTEGRATION_VAULT_KEY is required");

  return {
    /** Set or rotate a secret. Re-encrypts with a fresh IV and invalidates the vault cache. */
    async rotate(scope: CredentialScope, plaintext: string): Promise<void> {
      await deps.store.put(scope, encryptSecret(plaintext, deps.masterKey), now());
      deps.vault?.invalidate(keyOf(scope));
    },
    async reveal(scope: CredentialScope): Promise<string | undefined> {
      const ct = await deps.store.get(scope);
      return ct === undefined ? undefined : decryptSecret(ct, deps.masterKey);
    },
    async list(vendorId?: string): Promise<MaskedCredential[]> {
      const rows = await deps.store.list(vendorId);
      return rows.map((r) => ({
        scope: r.scope,
        masked: maskSecret(decryptSecret(r.ciphertext, deps.masterKey)),
        updatedAt: r.updatedAt.toISOString(),
      }));
    },
    /** Re-encrypt every row under a new master key (key rotation). */
    async rekey(newKey: string): Promise<number> {
      const rows = await deps.store.list();
      for (const r of rows) {
        await deps.store.put(r.scope, encryptSecret(decryptSecret(r.ciphertext, deps.masterKey), newKey), now());
      }
      deps.vault?.invalidate();
      return rows.length;
    },
  };
}

export type VaultAdmin = ReturnType<typeof createVaultAdmin>;

export async function createPrismaCredentialStore(): Promise<CredentialStore> {
  const { getPrisma } = await import("./db.ts");
  const db = await getPrisma();
  return {
    async put(scope, ciphertext) {
      if (scope.kind === "setting") {
        const existing = await db.integrationSetting.findFirst({ where: { vendorId: scope.vendorId, key: scope.key } });
        if (existing) await db.integrationSetting.update({ where: { id: existing.id }, data: { value: ciphertext } });
        else await db.integrationSetting.create({ data: { vendorId: scope.vendorId, key: scope.key, value: ciphertext } });
      } else {
        const driver = scope.driver as never;
        await db.vendorIntegrationCredential.upsert({
          where: { vendorId_driver: { vendorId: scope.vendorId, driver } },
          update: { credential: ciphertext },
          create: { vendorId: scope.vendorId, driver, credential: ciphertext },
        });
      }
    },
    async get(scope) {
      if (scope.kind === "setting") {
        return (await db.integrationSetting.findFirst({ where: { vendorId: scope.vendorId, key: scope.key } }))?.value;
      }
      return (await db.vendorIntegrationCredential.findUnique({
        where: { vendorId_driver: { vendorId: scope.vendorId, driver: scope.driver as never } },
      }))?.credential;
    },
    async list(vendorId) {
      const where = vendorId ? { vendorId } : {};
      const [s, d] = await Promise.all([
        db.integrationSetting.findMany({ where }),
        db.vendorIntegrationCredential.findMany({ where }),
      ]);
      return [
        ...s.map((r) => ({ scope: { kind: "setting", vendorId: r.vendorId, key: r.key } as CredentialScope, ciphertext: r.value, updatedAt: r.updatedAt })),
        ...d.map((r) => ({ scope: { kind: "driver", vendorId: r.vendorId, driver: r.driver } as CredentialScope, ciphertext: r.credential, updatedAt: r.updatedAt })),
      ];
    },
  };
}
