}

/** Rotate: body { vendorId, key } or { vendorId, driver }, plus { secret }. Secret is never echoed. */
export async function POST(request: Request) {
  const auth = await requireRole(request, "admin");
  if (!auth.ok) return auth.response;
  const b = (await request.json().catch(() => null)) as Record<string, unknown> | null;
  const secret = typeof b?.secret === "string" ? b.secret : "";
  const vendorId = typeof b?.vendorId === "string" ? b.vendorId : "";
  if (!b || !secret || !vendorId || (typeof b.key !== "string" && typeof b.driver !== "string")) {
    return Response.json({ error: "validation_failed", error_description: "vendorId, secret and key|driver required" }, { status: 400 });
  }
  const scope: CredentialScope =
    typeof b.driver === "string" ? { kind: "driver", vendorId, driver: b.driver } : { kind: "setting", vendorId, key: String(b.key) };
  await (await admin()).rotate(scope, secret);
  return Response.json({ ok: true });
}
