  const db = mk()
  assert.throws(() => g.createGoal(db, { scope: 'project', title: 't', ...A }), /project_id/)
  assert.throws(() => g.createGoal(db, { scope: 'organization', project_id: 'P', title: 't', ...A }), /cannot have project_id/)
