  g.createGoal(db, { id: 'O', scope: 'organization', title: 'Org', weight: 3, owner: 'ceo', status: 'active', ...A })
  g.createGoal(db, { id: 'C', scope: 'project', project_id: 'p', parent_id: 'O', title: 'Child', weight: null, owner: null, status: null, ...A })
