    if (!l.posAssigned) failures.push(`${l.id}: POS not assigned`);
  }
  return { ready: failures.length === 0, failures };
}

class EventOps {
  constructor({ now = () => new Date().toISOString(), secret = crypto.randomBytes(32), brands = [] } = {}) {
    this.now = now; this.secret = secret;
    this.brands = new Map(brands.map((b) => [b.id, M.Brand(b)]));
    this.events = new Map(); this.state = new Map(); this.audit = [];
    this.invitations = []; this.booths = new Map(); this.waitlist = [];
    this.tickets = []; this.scans = new Map(); this.shifts = []; this.issues = new Map();
    this.closeout = new Map();
  }
  _audit(actor, action, entity, entityId, detail) {
    const e = M.AuditEntry({ actor, action, entity, entityId, at: this.now() });
    this.audit.push(Object.freeze({ ...e, detail })); return e;
  }
  _need(role, perm) { if (!M.can(role, perm)) throw new Error(`forbidden: ${role} lacks ${perm}`); }

  createEvent(input, { actor, role }) {
    this._need(role, 'event:write');
    const ev = M.Event(input);
    this.events.set(ev.id, ev);
    this.state.set(ev.id, { status: 'draft', locations: [], reconciled: false, settled: false });
    this._audit(actor, 'create', 'event', ev.id); return ev;
  }
  setLocations(eventId, locations) { this.state.get(eventId).locations = locations; }
  statusOf(eventId) { return this.state.get(eventId).status; }
  openIssue(eventId, id) { (this.issues.get(eventId) || this.issues.set(eventId, new Set()).get(eventId)).add(id); }
  resolveIssue(eventId, id) { (this.issues.get(eventId) || new Set()).delete(id); }
  markReconciled(eventId, v = true) { this.state.get(eventId).reconciled = v; }
  markSettled(eventId, v = true) { this.state.get(eventId).settled = v; }

  /** Server-enforced transition; every attempt that succeeds writes an audit row. */
  transition(eventId, to, { actor, role, manualCloseout = false }) {
    this._need(role, 'event:write');
    const st = this.state.get(eventId); if (!st) throw new Error('unknown event');
    if (!NEXT[st.status].includes(to)) throw new Error(`illegal transition ${st.status} -> ${to}`);
    if (to === 'active') {
      const r = computeReadiness(st.locations);
      if (!r.ready) throw new Error(`readiness gate: ${r.failures.join('; ')}`);
    }
    if (to === 'closed') {
      if (!manualCloseout) throw new Error('closeout is manual: manualCloseout flag required');
      const open = (this.issues.get(eventId) || new Set()).size;
      if (!st.reconciled) throw new Error('closeout blocked: reconciliation outstanding');
      if (!st.settled) throw new Error('closeout blocked: settlement outstanding');
      if (open) throw new Error(`closeout blocked: ${open} unresolved issue(s)`);
    }
    const from = st.status; st.status = to;
    this._audit(actor, 'transition', 'event', eventId, { from, to }); return to;
  }

  /** Invite an existing brand; unknown brands are rejected (no new-brand creation path). */
  invite(eventId, brandId, { actor, role }) {
    this._need(role, 'brand:invite');
    if (!this.brands.has(brandId)) throw new Error(`unknown brand ${brandId}: only existing Ecom brands can be invited`);
    const inv = { eventId, brandId, outcome: 'pending', note: null };
    this.invitations.push(inv); this._audit(actor, 'invite', 'brand', brandId, { eventId }); return inv;
  }
  decideInvitation(eventId, brandId, outcome, { actor, role, note = null }) {
    this._need(role, 'brand:invite');
    if (!INVITE_OUTCOMES.includes(outcome)) throw new Error('invalid outcome');
    const inv = this.invitations.find((i) => i.eventId === eventId && i.brandId === brandId);
    if (!inv) throw new Error('no invitation');
    inv.outcome = outcome; inv.note = note;
    this._audit(actor, `invitation:${outcome}`, 'brand', brandId, { eventId }); return inv;
  }

  addBooth(input) { const b = M.Booth(input); this.booths.set(b.id, b); return b; }
  /** Manual booth allocation; approved brands only; taken booths push to the waitlist. */
  allocateBooth(boothId, brandId, { actor, role }) {
    this._need(role, 'booth:allocate');
    const b = this.booths.get(boothId); if (!b) throw new Error('unknown booth');
    const inv = this.invitations.find((i) => i.eventId === b.eventId && i.brandId === brandId);
    if (!inv || inv.outcome !== 'approve') throw new Error('brand not approved for this event');
    if (b.brandId) { this.waitlist.push({ boothId, brandId }); this._audit(actor, 'booth:waitlist', 'booth', boothId, { brandId }); return { status: 'waitlisted' }; }
    this.booths.set(boothId, Object.freeze({ ...b, brandId }));
    this._audit(actor, 'booth:allocate', 'booth', boothId, { brandId }); return { status: 'allocated' };
  }

  addTicketType(input, { capacity = Infinity, minAge = 0 } = {}) {
    const t = M.Ticket(input); this.tickets.push({ ...t, capacity, minAge, sold: 0 }); return t;
  }
  /** Sell a ticket: capacity, age gate (DOB), and every registration requirement enforced. */
  sellTicket(ticketId, attendee) {
    const t = this.tickets.find((x) => x.id === ticketId); if (!t) throw new Error('unknown ticket');
    if (t.sold >= t.capacity) throw new Error('sold out');
    if (t.minAge) {
      const dob = Date.parse(attendee.dob), ref = Date.parse(this.now());
      if (Number.isNaN(dob) || (ref - dob) / (365.2425 * 864e5) < t.minAge) throw new Error(`age gate: ${t.minAge}+ required`);
    }
    for (const req of t.requirements) if (!attendee.provided || !attendee.provided.includes(req)) throw new Error(`missing requirement: ${req}`);
    t.sold += 1;
    const serial = crypto.randomBytes(8).toString('hex');
    return { serial, token: this._sign(`${t.eventId}.${t.id}.${serial}`) };
  }
  /** Opaque signed token: no PII, no user id. */
  _sign(payload) {
    const mac = crypto.createHmac('sha256', this.secret).update(payload).digest('hex').slice(0, 32);
    return Buffer.from(`${payload}.${mac}`).toString('base64url');
  }
  /** Scan = verify signature, then reject replays (per serial, per zone). */
  scan(token, { zone = 'gate', device = 'unknown' } = {}) {
    let raw; try { raw = Buffer.from(token, 'base64url').toString(); } catch { return { ok: false, reason: 'malformed' }; }
    const i = raw.lastIndexOf('.'); if (i < 0) return { ok: false, reason: 'malformed' };
    const payload = raw.slice(0, i), mac = raw.slice(i + 1);
    const want = crypto.createHmac('sha256', this.secret).update(payload).digest('hex').slice(0, 32);
    if (mac.length !== want.length || !crypto.timingSafeEqual(Buffer.from(mac), Buffer.from(want))) return { ok: false, reason: 'bad signature' };
    const key = `${payload}|${zone}`;
    if (this.scans.has(key)) return { ok: false, reason: 'replay', first: this.scans.get(key) };
    this.scans.set(key, { device, at: this.now() }); return { ok: true };
  }

  /** Staff shifts; a staff member cannot be double-booked. */
  addShift(input, { actor, role }) {
    this._need(role, 'staff:schedule');
    const s = M.StaffShift(input);
    const clash = this.shifts.find((x) => x.staffUserId === s.staffUserId
      && Date.parse(s.start) < Date.parse(x.end) && Date.parse(x.start) < Date.parse(s.end));
    if (clash) throw new Error(`shift overlaps ${clash.id}`);
    this.shifts.push(s); this._audit(actor, 'shift:add', 'shift', s.id); return s;
  }
}

module.exports = { EventOps, LIFECYCLE, INVITE_OUTCOMES, computeReadiness };
