body='''export const METRC_CA_PROD_URL = "https://api-ca.metrc.com";
export const METRC_CA_SANDBOX_URL = "https://sandbox-api-ca.metrc.com";

export interface MetrcDriverOptions {
  fetch?: MetrcFetch;
  store?: ComplianceRecordStore;
}

const defaultFetch: MetrcFetch = (url, init) => (globalThis as any).fetch(url, init);

/**
 * Metrc compliance driver for California. Sandbox (deterministic, no HTTP) when
 * no METRC keys; live mode makes real Metrc calls and FAILS CLOSED: any
 * transport error, non-2xx status, licence mismatch or insufficient package
 * quantity is a recorded failure and the order is not released.
 *
 * Live checks (HTTP Basic vendorKey:userKey, licenseNumber query param):
 *  - GET /facilities/v1: the order licence must be a facility we can act for.
 *  - GET /packages/v1/active: every item (sku matched to the package Label or
 *    Item.Name) needs an active package with enough Quantity.
 */
export class MetrcComplianceDriver implements ComplianceDriver {
  readonly system = "metrc" as const;
  private readonly seen = new Map<string, number>();
  private readonly fetchImpl: MetrcFetch;
  private readonly store?: ComplianceRecordStore;

  constructor(private readonly vault: CredentialVault, options: MetrcDriverOptions = {}) {
    this.fetchImpl = options.fetch ?? defaultFetch;
    this.store = options.store;
  }

  private async keys() {
    const vendorKey = await this.vault.get("METRC_VENDOR_KEY");
    const userKey = await this.vault.get("METRC_USER_KEY");
    return { vendorKey, userKey, sandbox: !vendorKey || !userKey };
  }

  private async get(base: string, path: string, licence: string, auth: string) {
    const url = `${base}${path}?licenseNumber=${encodeURIComponent(licence)}`;
    const res = await this.fetchImpl(url, { method: "GET", headers: { authorization: auth, accept: "application/json" } });
    if (!res.ok) throw new Error(`metrc ${path} returned HTTP ${res.status}`);
    return { url, body: await res.json() };
  }

  private async liveCheck(
    request: ComplianceCheckRequest,
    vendorKey: string,
    userKey: string,
  ): Promise<{ passed: boolean; reason?: string; response: unknown }> {
    const explicit = await this.vault.get("METRC_API_BASE");
    const useSandbox = (await this.vault.get("METRC_ENV")) === "sandbox";
    const base = (explicit || (useSandbox ? METRC_CA_SANDBOX_URL : METRC_CA_PROD_URL)).replace(/\\/+$/, "");
    const licence = request.licenceNumber ?? (await this.vault.get("METRC_LICENSE_NUMBER"));
    if (!licence) return { passed: false, reason: "no licence number for Metrc call", response: null };
    const auth = `Basic ${Buffer.from(`${vendorKey}:${userKey}`).toString("base64")}`;

    const facilities = await this.get(base, "/facilities/v1", licence, auth);
    const list: any[] = Array.isArray(facilities.body) ? facilities.body : [];
    const facility = list.find((f) => f?.License?.Number === licence || f?.LicenseNumber === licence);
    if (!facility) {
      return { passed: false, reason: `licence ${licence} not found in Metrc facilities`, response: { facilities: list.length } };
    }

    const packages = await this.get(base, "/packages/v1/active", licence, auth);
    const pkgs: any[] = Array.isArray(packages.body) ? packages.body : [];
    const shortages: string[] = [];
    for (const item of request.items) {
      const available = pkgs
        .filter((p) => p?.Label === item.sku || p?.Item?.Name === item.sku || p?.ProductName === item.sku)
        .reduce((acc, p) => acc + (Number(p?.Quantity) || 0), 0);
      if (available < item.quantity) shortages.push(`${item.sku}: need ${item.quantity}, Metrc has ${available}`);
    }
    const response = { facility: facility?.Name ?? licence, packagesChecked: pkgs.length, shortages };
    return shortages.length ? { passed: false, reason: `insufficient Metrc inventory (${shortages.join("; ")})`, response } : { passed: true, response };
  }

  async complianceCheck(request: ComplianceCheckRequest): Promise<ComplianceCheckResult> {
    const { vendorKey, userKey, sandbox } = await this.keys();
    const retryCount = this.seen.get(request.orderId) ?? 0;
    this.seen.set(request.orderId, retryCount + 1);

    const requestBody = {
      orderId: request.orderId,
      kind: request.kind,
      items: request.items,
      licence: request.licenceNumber
        ? { licenceNumber: request.licenceNumber, state: request.issuingState }
        : undefined,
    };

    let passed: boolean;
    let reason: string | undefined;
    let responseBody: unknown;
    if (sandbox) {
      // Deterministic sandbox: pass, except a deliberately-invalid request
      // (no items) fails, exercising the recorded-failure path.
      passed = request.items.length > 0;
      reason = passed ? undefined : "sandbox: empty compliance request";
      responseBody = { sandbox: true, status: passed ? "passed" : "rejected" };
    } else if (request.items.length === 0) {
      passed = false;
      reason = "empty compliance request";
      responseBody = { status: "rejected" };
    } else {
      try {
        const r = await this.liveCheck(request, vendorKey!, userKey!);
        passed = r.passed;
        reason = r.reason;
        responseBody = { status: passed ? "passed" : "rejected", ...(r.response as object) };
      } catch (err) {
        passed = false;
        reason = `metrc call failed: ${(err as Error).message}`;
        responseBody = { status: "error" };
      }
    }

    const record = buildComplianceRecord(request, "metrc", passed, reason, requestBody, responseBody, retryCount);
    // Persist on pass AND fail. A failed write is surfaced, never swallowed:
    // releasing an order with no audit row is the worse outcome.
    if (this.store) await this.store.save(record);
    return { record, passed, sandbox };
  }
}

/** Return the compliance driver (only Metrc/CA is built; BioTrackTHC would slot in here). */
export function getComplianceDriver(vault: CredentialVault, options: MetrcDriverOptions = {}): ComplianceDriver {
  return new MetrcComplianceDriver(vault, options);
}
