// Stripe sandbox adapter (Claude Sonnet 5.5). Active only with an sk_test_ key (isConfigured);
// a live key is refused so the registry falls back to the mock. Uses the REST API via injectable fetch.
import type { PaymentAdapter, CreateIntentResult, CaptureResult, RefundResult, SplitResult, PayoutResult } from '../adapter.ts';
import { providerRequest, formEncode, type FetchLike } from './http.ts';

const BASE = 'https://api.stripe.com';
const KEY_RE = /^sk_test_[A-Za-z0-9]+$/;

type Env = Record<string, string | undefined>;

export function isConfigured(env: Env = process.env): boolean {
  return KEY_RE.test((env.STRIPE_SECRET_KEY ?? '').trim());
}

function mapIntentStatus(s: string): CreateIntentResult['status'] {
  if (s === 'succeeded') return 'succeeded';
  if (s === 'requires_capture') return 'requires_capture';
  if (s === 'processing') return 'processing';
  if (s === 'canceled') return 'failed';
  return 'requires_action';
}

export function createStripeAdapter(opts: { fetch?: FetchLike; env?: Env } = {}): PaymentAdapter {
  const fetchImpl = opts.fetch ?? fetch;
  const env = opts.env ?? process.env;
  const call = (path: string, params: Record<string, string | number | undefined>) =>
    providerRequest('stripe', fetchImpl, `${BASE}${path}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${(env.STRIPE_SECRET_KEY ?? '').trim()}`,
        'Content-Type': 'application/x-www-form-urlencoded',
      },
      body: formEncode(params),
    });
  return {
    provider: 'stripe',
    async createIntent(req): Promise<CreateIntentResult> {
      const params: Record<string, string | number | undefined> = {
        amount: req.amount.amount,
        currency: req.amount.currency.toLowerCase(),
        capture_method: 'manual',
        'automatic_payment_methods[enabled]': 'true',
        description: req.description,
        'metadata[orderId]': req.orderId,
      };
      for (const [k, v] of Object.entries(req.metadata ?? {})) params[`metadata[${k}]`] = v;
      const pi = await call('/v1/payment_intents', params);
      return { provider: 'stripe', intentId: pi.id, clientSecret: pi.client_secret, status: mapIntentStatus(pi.status), raw: pi };
    },
    async capture(req): Promise<CaptureResult> {
      const pi = await call(`/v1/payment_intents/${encodeURIComponent(req.intentId)}/capture`, {
        amount_to_capture: req.amount?.amount,
      });
      const status = pi.status === 'succeeded' ? 'succeeded' : pi.status === 'processing' ? 'processing' : 'failed';
      return {
        provider: 'stripe',
        intentId: pi.id,
        status,
        capturedAmount: pi.amount_received != null ? { amount: pi.amount_received, currency: pi.currency } : undefined,
        raw: pi,
      };
    },
    async refund(req): Promise<RefundResult> {
      const r = await call('/v1/refunds', { payment_intent: req.intentId, amount: req.amount?.amount, reason: undefined });
      const status = r.status === 'succeeded' ? 'succeeded' : r.status === 'pending' ? 'pending' : 'failed';
      return {
        provider: 'stripe',
        refundId: r.id,
        intentId: req.intentId,
        status,
        refundedAmount: { amount: r.amount, currency: r.currency },
        raw: r,
      };
    },
    async split(req): Promise<SplitResult> {
      const transfers = [];
      for (const t of req.targets) {
        const tr = await call('/v1/transfers', {
          amount: t.amount.amount,
          currency: t.amount.currency.toLowerCase(),
          destination: t.destinationAccountId,
          transfer_group: req.intentId,
        });
        transfers.push({ destinationAccountId: t.destinationAccountId, transferId: tr.id, amount: t.amount });
      }
      return { provider: 'stripe', intentId: req.intentId, transfers };
    },
    async payout(req): Promise<PayoutResult> {
      const tr = await call('/v1/transfers', {
        amount: req.amount.amount,
        currency: req.amount.currency.toLowerCase(),
        destination: req.destinationAccountId,
        description: req.description,
      });
      return { provider: 'stripe', payoutId: tr.id, destinationAccountId: req.destinationAccountId, status: 'paid', amount: req.amount, raw: tr };
    },
  };
}

