export function createPayMongoAdapter(opts: { fetch?: FetchLike; env?: Env } = {}): PaymentAdapter {
  const fetchImpl = opts.fetch ?? fetch;
  const env = opts.env ?? process.env;
  const call = (path: string, body: unknown) =>
    providerRequest('paymongo', fetchImpl, `${BASE}${path}`, {
      method: 'POST',
      headers: { Authorization: basicAuth((env.PAYMONGO_SECRET_KEY ?? '').trim()), 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
  return {
    provider: 'paymongo',
    async createIntent(req): Promise<CreateIntentResult> {
      const res = await call('/payment_intents', {
        data: {
          attributes: {
            amount: req.amount.amount,
            currency: req.amount.currency.toUpperCase(),
            payment_method_allowed: ['card', 'gcash'],
            capture_type: 'manual',
            description: req.description,
            metadata: { orderId: req.orderId },
          },
        },
      });
      const a = res.data.attributes;
      const status = a.status === 'succeeded' ? 'succeeded' : a.status === 'processing' ? 'processing' : a.status === 'awaiting_capture' ? 'requires_capture' : 'requires_action';
      return { provider: 'paymongo', intentId: res.data.id, clientSecret: a.client_key, status, raw: res };
    },
    async capture(req): Promise<CaptureResult> {
      const res = await call(`/payment_intents/${encodeURIComponent(req.intentId)}/capture`, {
        data: { attributes: { amount: req.amount?.amount } },
      });
      const a = res.data.attributes;
      return {
        provider: 'paymongo',
        intentId: res.data.id,
        status: a.status === 'succeeded' ? 'succeeded' : a.status === 'processing' ? 'processing' : 'failed',
        capturedAmount: { amount: a.amount, currency: a.currency },
        raw: res,
      };
    },
    async refund(req): Promise<RefundResult> {
      const res = await call('/refunds', {
        data: { attributes: { payment_id: req.intentId, amount: req.amount?.amount, reason: 'others', notes: req.reason } },
      });
      const a = res.data.attributes;
      return {
        provider: 'paymongo',
        refundId: res.data.id,
        intentId: req.intentId,
        status: a.status === 'succeeded' ? 'succeeded' : a.status === 'failed' ? 'failed' : 'pending',
        refundedAmount: { amount: a.amount, currency: a.currency },
        raw: res,
      };
    },
  };
}

