// Coinbase Commerce adapter (Claude Sonnet 5.5). Coinbase Commerce has no sandbox, so it is active
// only when COINBASE_COMMERCE_TEST_API_KEY is set explicitly (a throwaway/test account key).
// Charges settle off-platform: createIntent -> requires_action, capture polls the charge timeline.
import type { PaymentAdapter, CreateIntentResult, CaptureResult, RefundResult } from '../adapter.ts';
import { providerRequest, type FetchLike } from './http.ts';

const BASE = 'https://api.commerce.coinbase.com';
type Env = Record<string, string | undefined>;

export function isConfigured(env: Env = process.env): boolean {
  return (env.COINBASE_COMMERCE_TEST_API_KEY ?? '').trim().length > 0;
}

export function chargeStatus(timeline: Array<{ status: string }> | undefined): CaptureResult['status'] {
  const last = timeline?.[timeline.length - 1]?.status;
  if (last === 'COMPLETED' || last === 'RESOLVED') return 'succeeded';
  if (last === 'EXPIRED' || last === 'CANCELED' || last === 'UNRESOLVED') return 'failed';
  return 'processing';
}

export function createCoinbaseCommerceAdapter(opts: { fetch?: FetchLike; env?: Env } = {}): PaymentAdapter {
  const fetchImpl = opts.fetch ?? fetch;
  const env = opts.env ?? process.env;
  const headers = () => ({
    'X-CC-Api-Key': (env.COINBASE_COMMERCE_TEST_API_KEY ?? '').trim(),
    'X-CC-Version': '2018-03-22',
    'Content-Type': 'application/json',
  });
  return {
    provider: 'coinbase_commerce',
    async createIntent(req): Promise<CreateIntentResult> {
      const res = await providerRequest('coinbase_commerce', fetchImpl, `${BASE}/charges`, {
        method: 'POST',
        headers: headers(),
        body: JSON.stringify({
          name: req.description ?? `Order ${req.orderId}`,
          pricing_type: 'fixed_price',
          local_price: { amount: (req.amount.amount / 100).toFixed(2), currency: req.amount.currency.toUpperCase() },
          metadata: { orderId: req.orderId },
        }),
      });
      return { provider: 'coinbase_commerce', intentId: res.data.code, clientSecret: res.data.hosted_url, status: 'requires_action', raw: res };
    },
    async capture(req): Promise<CaptureResult> {
      const res = await providerRequest('coinbase_commerce', fetchImpl, `${BASE}/charges/${encodeURIComponent(req.intentId)}`, {
        method: 'GET',
        headers: headers(),
      });
      return { provider: 'coinbase_commerce', intentId: req.intentId, status: chargeStatus(res.data.timeline), raw: res };
    },
    async refund(req): Promise<RefundResult> {
      throw new Error('coinbase_commerce: on-chain payments cannot be refunded through the API; refund manually');
    },
  };
}

export const createAdapter = () => createCoinbaseCommerceAdapter();
