// Shared fetch helper for the sandbox payment adapters (Claude Sonnet 5.5).
// Every adapter takes an injectable fetch so tests run on recorded fixtures with no network.
export type FetchLike = typeof fetch;

export class ProviderHttpError extends Error {
  status: number;
  code?: string;
  constructor(provider: string, status: number, message: string, code?: string) {
    super(`${provider} ${status}: ${message}`);
    this.status = status;
    this.code = code;
  }
}

export async function providerRequest(
  provider: string,
  fetchImpl: FetchLike,
  url: string,
  init: { method?: string; headers?: Record<string, string>; body?: string },
): Promise<any> {
  const res = await fetchImpl(url, init);
  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = null;
  }
  if (!res.ok) {
    const msg = json?.error?.message ?? json?.errors?.[0]?.detail ?? json?.message ?? json?.error ?? text.slice(0, 200);
    const code = json?.error?.code ?? json?.error?.decline_code ?? json?.errors?.[0]?.code ?? json?.code;
    throw new ProviderHttpError(provider, res.status, String(msg), typeof code === 'string' ? code : undefined);
  }
  return json;
}

export function formEncode(obj: Record<string, string | number | undefined>): string {
  return Object.entries(obj)
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&');
}

export function basicAuth(key: string): string {
  return `Basic ${Buffer.from(`${key}:`).toString('base64')}`;
}
