        data: { attributes: { amount: req.amount?.amount } },
      });
      const a = res.data.attributes;
      return {
        provider: 'paymongo',
        intentId: res.data.id,
        status: a.status === 'succeeded' ? 'succeeded' : a.status === 'processing' ? 'processing' : 'failed',
        capturedAmount: { amount: a.amount, currency: a.currency },
        raw: res,
      };
    },
    async refund(req): Promise<RefundResult> {
      const res = await call('/refunds', {
        data: { attributes: { payment_id: req.intentId, amount: req.amount?.amount, reason: 'others', notes: req.reason } },
