// Payment drivers: per-vendor B2C rails, B2B rails, exactly-once settlement (Claude Sonnet 5.5).
import { test } from "node:test";
import assert from "node:assert/strict";
import {
  getPaymentDriver,
  selectB2cMethod,
  MemorySettlementStore,
  PrismaSettlementStore,
} from "../src/drivers/payment.ts";

const vault = (m: Record<string, string>) => ({ get: async (k: string) => m[k] }) as any;
const claim = (method: any, key = "ord1") => ({ orderId: key, amountCents: 12345, method, idempotencyKey: key });

function replay(routes: Record<string, { status?: number; body: unknown }>) {
  const calls: { key: string; body?: any }[] = [];
  const f = async (url: string, init?: any) => {
    const key = `${init?.method ?? "GET"} ${url}`;
    calls.push({ key, body: init?.body ? JSON.parse(init.body) : undefined });
    const r = routes[key];
    if (!r) return { ok: false, status: 404, json: async () => ({}) };
    const status = r.status ?? 200;
    return { ok: status < 400, status, json: async () => r.body };
  };
  return { f: f as any, calls };
}
const captures = (calls: { key: string }[]) => calls.filter((c) => /capture|\/transfers\/[^/]+$|status/.test(c.key) && !c.key.startsWith("POST https://sandbox.pay.dutchie.com/v1/payments ")).length;

test("sandbox (no keys): claim then confirm settles once, retry is already_settled", async () => {
  for (const m of ["dutchie_pay", "treez_pay", "crypto", "ach"] as const) {
