    const d = getPaymentDriver(m, vault({}), { store });
    const c = await d.claim(claim(m));
    assert.equal(c.sandbox, true, m);
    assert.equal((await d.confirm(c.claimRef)).status, "settled", m);
    // webhook retry through a brand-new driver instance
    const again = await getPaymentDriver(m, vault({}), { store }).confirm(c.claimRef);
    assert.equal(again.status, "already_settled", m);
  }
});

