test("PrismaSettlementStore: one conditional UPDATE wins, release reopens", async () => {
  const rows = new Map<string, any>();
  const prisma = {
    paymentRequest: {
      findFirst: async ({ where }: any) => rows.get(where.providerRef) ?? null,
      create: async ({ data }: any) => void rows.set(data.providerRef, { id: "pr_1", ...data }),
      updateMany: async ({ where, data }: any) => {
