        if (!r) return { count: 0 };
        const ok = where.status?.not ? r.status !== where.status.not : r.status === where.status;
        if (!ok) return { count: 0 };
        Object.assign(r, data);
        return { count: 1 };
      },
    },
  };
  const store = new PrismaSettlementStore(async () => prisma as any);
  await store.open("ref1", { orderId: "o1", method: "ach", amountCents: 500 });
  await store.open("ref1", { orderId: "o1", method: "ach", amountCents: 500 });
