  assert.equal(rows.get("ref1").amountCents, 500n);
  assert.equal(await store.tryClaim("ref1"), true);
  assert.equal(await store.tryClaim("ref1"), false);
  assert.equal(await store.isSettled("ref1"), true);
  await store.release("ref1");
  assert.equal(await store.isSettled("ref1"), false);
  assert.equal(await store.tryClaim("ref1"), true);
});
