export interface PayoutExecuteDeps {
  authorize(): Promise<Caller>;
  execute(input: { payoutId: string; mode: "manual" | "rail"; reference?: string | null }): Promise<Record<string, unknown> & { failed?: boolean }>;
}

// POST /api/ledger/payouts/:payoutId/execute  Body: { mode?: "manual" | "rail", reference? }
export async function handlePayoutExecute(payoutId: string, rawBody: unknown, deps: PayoutExecuteDeps): Promise<HandlerResult> {
  const denied = await adminOnly(deps.authorize);
  if (denied) return denied;
  const b = obj(rawBody);
  const mode = b.mode ?? "manual";
  if (mode !== "manual" && mode !== "rail") return { status: 400, body: { error: 'mode must be "manual" or "rail"' } };
  if (b.reference !== undefined && b.reference !== null && (typeof b.reference !== "string" || b.reference.length > 200)) {
    return { status: 400, body: { error: "reference must be a string (max 200 chars)" } };
  }
  try {
    const result = await deps.execute({ payoutId, mode, reference: (b.reference as string | null | undefined) ?? null });
    return { status: result.failed ? 502 : 200, body: result };
  } catch (err) {
    if (err instanceof PayoutError) return { status: err.status, body: { error: err.message } };
    throw err;
  }
}

export interface PayoutHistoryDeps {
  authorize(): Promise<Caller>;
  list(filter: { vendorId?: string; status?: string }): Promise<unknown[]>;
}

const PAYOUT_STATUSES = ["PENDING", "PROCESSING", "COMPLETED", "FAILED"];

// GET /api/ledger/payouts/history?vendorId=&status=
export async function handlePayoutHistory(params: URLSearchParams, deps: PayoutHistoryDeps): Promise<HandlerResult> {
  const denied = await adminOnly(deps.authorize);
  if (denied) return denied;
  const status = params.get("status") || undefined;
  if (status && !PAYOUT_STATUSES.includes(status)) return { status: 400, body: { error: `status must be one of ${PAYOUT_STATUSES.join(", ")}` } };
  const payouts = await deps.list({ vendorId: params.get("vendorId") || undefined, status });
  return { status: 200, body: { payouts } };
}
