export const dynamic = "force-dynamic";

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { requireRole } from "@/lib/roles";
import { handlePayoutExecute } from "@/lib/ledger/handlers";
import { executePayout } from "@/lib/ledger/payoutExecution";
import { getPaymentAdapter } from "@/lib/payments/registry";

// POST /api/ledger/payouts/:payoutId/execute — { mode?: "manual" | "rail", reference? } (admin only).
// manual: mark a PENDING payout paid. rail: send via the configured rail's payout() (Stripe sandbox);
// a failed transfer marks the payout FAILED and reverses its journal entry.
export async function POST(request: Request, { params }: { params: { payoutId: string } }) {
  let body: unknown = null;
  try {
    body = await request.json();
  } catch {
    body = null;
  }
  const result = await handlePayoutExecute(params.payoutId, body, {
    authorize: () => requireRole(request, "ADMIN"),
    execute: async (input) =>
      executePayout(prisma, {
        ...input,
        adapter: input.mode === "rail" ? await getPaymentAdapter({ PAYMENT_PROVIDER: "stripe" }) : undefined,
      }),
  });
  return NextResponse.json(result.body, { status: result.status });
}
