// Admin-tunable lead configuration (Q26 weights/thresholds, Q48 authorization
// thresholds, Q52 follow-up mode/templates, Q47 stalled-lead rule, qualification
// checklists by region/industry/lead type). Stored as one JSON Setting
// (LEAD_CONFIG) — lib/leads/store.js reads/merges it; this file is pure.

export const SCORE_VERSION = "lead-score-v1";

export const DEFAULT_LEAD_CONFIG = {
  weights: { financial: 30, suitability: 25, quality: 15, sourceConfidence: 15, conversion: 15 },
  qualifyThreshold: 60,
  // Below this share of known weight a score is flagged as resting on thin data.
  minCoverage: 0.5,
  // Q48: SAM / proposal actions inside these limits need only an explicit
  // admin action; outside them an explicit admin override is also required.
  authorization: { samMaxSystemKw: 1000, proposalMaxInstallCostUsd: 2000000 },
  // Q52: AUTO queues follow-ups as READY; APPROVAL_GATED holds each until an admin approves it.
  followUps: {
    mode: "APPROVAL_GATED",
    templates: [
      { id: "fu-3d", afterDays: 3, subject: "Following up on your solar proposal", body: "Checking in on the preliminary proposal we sent. Happy to walk through the assumptions." },
      { id: "fu-10d", afterDays: 10, subject: "Any questions on the solar proposal?", body: "Let us know if you would like a revised scenario or a site visit." },
    ],
  },
  // Q47: pm flags stalled leads and recommends reassignment; auto-reassign only if enabled.
  stalled: { afterDays: 7, autoReassign: false },
  // Declarative checklists. Evaluated by lib/leads/qualification.js against the
  // lead payload; a missing path is "unknown", never "met".
  checklists: {
    default: [
      { id: "site-coords", label: "Site coordinates known", required: true, path: "site.lat", op: "present" },
      { id: "roof-area", label: "Usable roof area at least 500 sq ft", required: true, path: "site.roofAreaSqFt", op: "gte", value: 500 },
      { id: "ownership", label: "Owner or authorized lessee", required: true, path: "lead.ownership", op: "in", value: ["OWNER", "AUTHORIZED_LESSEE"] },
      { id: "contact", label: "Contact email or phone present", required: false, path: "lead.contact.email", op: "present" },
    ],
    byRegion: {},
    byIndustry: {},
    byLeadType: {
      COMMERCIAL: [{ id: "monthly-bill", label: "Monthly bill known (PHP)", required: false, path: "site.monthlyBillPhp", op: "present" }],
    },
  },
};

export function mergeLeadConfig(stored) {
  const s = stored && typeof stored === "object" ? stored : {};
  const d = DEFAULT_LEAD_CONFIG;
  return {
    ...d,
    ...s,
    weights: { ...d.weights, ...(s.weights || {}) },
    authorization: { ...d.authorization, ...(s.authorization || {}) },
    followUps: { ...d.followUps, ...(s.followUps || {}) },
    stalled: { ...d.stalled, ...(s.stalled || {}) },
    checklists: { ...d.checklists, ...(s.checklists || {}) },
  };
}

// Returns an error string or null.
export function validateLeadConfig(cfg) {
  const w = cfg.weights || {};
  for (const k of Object.keys(DEFAULT_LEAD_CONFIG.weights)) {
    if (typeof w[k] !== "number" || !Number.isFinite(w[k]) || w[k] < 0) return `weights.${k} must be a non-negative number`;
  }
  if (Object.values(w).reduce((a, b) => a + b, 0) <= 0) return "weights must not all be zero";
  if (typeof cfg.qualifyThreshold !== "number" || cfg.qualifyThreshold < 0 || cfg.qualifyThreshold > 100) return "qualifyThreshold must be 0-100";
  if (!["AUTO", "APPROVAL_GATED"].includes(cfg.followUps?.mode)) return "followUps.mode must be AUTO or APPROVAL_GATED";
  return null;
