import { SCORE_VERSION } from "@/lib/leads/config";

// Lead score = financial potential + suitability + lead quality + source
// confidence + conversion probability (Q26), admin-weighted. Mirrors the L7
// fit-score contract in billboard-platform (read-only reference): a component
// with no data contributes nothing AND leaves the denominator, so the score
// means "of what is known, this much fits"; `coverage` reports how much weight
// was known, and thin coverage is flagged rather than trusted. Commercial
// attractiveness stays separate from confidence (sourceConfidence is its own
// component, and unknown never scores as a positive).

const clamp01 = (n) => Math.max(0, Math.min(1, n));
const num = (v) => (typeof v === "number" && Number.isFinite(v) ? v : null);

export const COMPONENTS = {
  financial: (l) => {
    const payback = l.sam?.paybackYears;
    const kw = num(l.sam?.systemSizeKw);
    if (payback === null && l.sam && "paybackYears" in l.sam) return 0; // modeled, never pays back
    if (num(payback) !== null) return payback <= 4 ? 1 : payback <= 7 ? 0.75 : payback <= 10 ? 0.45 : 0.15;
    if (kw !== null) return clamp01(kw / 200) * 0.5; // size alone is weak evidence of value
    return null;
  },
  suitability: (l) => {
    const area = num(l.site?.roofAreaSqFt);
    if (area === null) return null;
    const shade = num(l.site?.shadeFactor);
    const areaRatio = clamp01(area / 5000);
    return shade === null ? areaRatio * 0.7 : areaRatio * (0.5 + 0.5 * clamp01(shade));
  },
  quality: (l) => {
    if (!l.lead) return null;
    const c = l.lead.contact || {};
    const parts = [!!c.email, !!c.phone, !!l.lead.organization, !!l.site?.address];
    return parts.filter(Boolean).length / parts.length;
  },
  sourceConfidence: (l) => {
    const direct = num(l.sourceConfidence);
    if (direct !== null) return clamp01(direct);
    const ev = (l.evidence || []).map((e) => num(e.confidence)).filter((x) => x !== null);
    return ev.length ? clamp01(ev.reduce((a, b) => a + b, 0) / ev.length) : null;
  },
  conversion: (l) => {
    const e = l.engagement;
    if (!e) return null;
    return clamp01((e.replied ? 0.4 : 0) + (e.meetingBooked ? 0.4 : 0) + (e.requestedProposal ? 0.2 : 0));
  },
};

export function scoreLead(lead, config) {
  const weights = config.weights;
  const breakdown = [];
  let total = 0;
  let known = 0;
  let earned = 0;
  for (const [id, fn] of Object.entries(COMPONENTS)) {
    const weight = weights[id] ?? 0;
    total += weight;
    const ratio = fn(lead);
    if (ratio === null) {
      breakdown.push({ id, weight, ratio: null, points: 0, known: false });
      continue;
    }
    known += weight;
    earned += weight * ratio;
    breakdown.push({ id, weight, ratio, points: weight * ratio, known: true });
  }
  const score = known > 0 ? Math.round((earned / known) * 1000) / 10 : 0;
  const coverage = total > 0 ? Math.round((known / total) * 100) / 100 : 0;
  const flags = [];
  if (coverage < config.minCoverage) flags.push("SCORE_DATA_INCOMPLETE");
  return { score, coverage, breakdown, flags, version: SCORE_VERSION };
}
