import { scoreLead } from "@/lib/leads/scoring";

// Configurable qualification checklists by region / industry / lead type, plus
// the verdict. Unknown stays unknown: a required item whose input is missing
// holds the lead at NEEDS_INFO instead of passing it, and no SAM result can
// turn an unknown qualification into "met".

export function getPath(obj, path) {
  return path.split(".").reduce((o, k) => (o == null ? undefined : o[k]), obj);
}

export function resolveChecklist(lead, config) {
  const c = config.checklists;
  const items = [...(c.default || [])];
  const add = (list) => list && items.push(...list.filter((i) => !items.some((e) => e.id === i.id)));
  add(c.byRegion?.[lead.lead?.region]);
  add(c.byIndustry?.[lead.lead?.industry]);
  add(c.byLeadType?.[lead.lead?.leadType]);
  return items;
}

export function evaluateItem(item, lead) {
  const v = getPath(lead, item.path);
  if (v === undefined || v === null || v === "") return "unknown";
  switch (item.op) {
    case "present": return "met";
    case "gte": return typeof v === "number" && v >= item.value ? "met" : "unmet";
    case "lte": return typeof v === "number" && v <= item.value ? "met" : "unmet";
    case "eq": return v === item.value ? "met" : "unmet";
    case "in": return Array.isArray(item.value) && item.value.includes(v) ? "met" : "unmet";
    default: return "unknown";
  }
}

export function qualifyLead(lead, config) {
  const checklist = resolveChecklist(lead, config).map((item) => ({ ...item, result: evaluateItem(item, lead) }));
  const score = scoreLead(lead, config);
  const blocks = checklist.filter((i) => i.required && i.result === "unmet").map((i) => i.id);
  const missing = checklist.filter((i) => i.required && i.result === "unknown").map((i) => i.id);
  let outcome;
  if (blocks.length) outcome = "REJECTED";
  else if (missing.length) outcome = "NEEDS_INFO";
  else outcome = score.score >= config.qualifyThreshold ? "QUALIFIED" : "REJECTED";
  return { outcome, score, checklist, blocks, missing };
}

// Q48: explicit SAM/proposal authorization within admin thresholds. Always
// needs an explicit action; out-of-policy additionally needs an admin override.
export function authorizeAction({ action, lead, config, explicit = false, adminOverride = false }) {
  if (!explicit) return { allowed: false, reason: "EXPLICIT_AUTHORIZATION_REQUIRED" };
  const a = config.authorization;
  let outOfPolicy = false;
  if (action === "SAM_ANALYSIS") {
    const kw = lead.sam?.systemSizeKw ?? lead.site?.desiredSystemKw;
    outOfPolicy = typeof kw === "number" && kw > a.samMaxSystemKw;
  } else if (action === "PROPOSAL") {
    const cost = lead.sam?.installCostUsd;
    outOfPolicy = typeof cost === "number" && cost > a.proposalMaxInstallCostUsd;
  } else {
    return { allowed: false, reason: "UNKNOWN_ACTION" };
  }
  if (outOfPolicy && !adminOverride) return { allowed: false, reason: "OUT_OF_POLICY_NEEDS_ADMIN_OVERRIDE" };
  return { allowed: true, reason: outOfPolicy ? "ADMIN_OVERRIDE" : "WITHIN_POLICY" };
}
