// Preliminary proposal drafts (Q25/Q51), follow-ups (Q52) and stalled-lead
// recommendations (Q47). Pure functions; lib/leads/store.js persists results.
//
// Rules carried from the plan: every displayed factual claim carries evidence
// ids; unknown answers are flagged UNKNOWN, never invented; a null payback is
// explained, not hidden; sending is recorded only for an APPROVED proposal and
// is never outreach by itself (separate authorization, acceptance test 10).

export function draftProposal(lead, qualification, { now = new Date(), evidenceIds = null } = {}) {
  if (qualification.outcome !== "QUALIFIED") throw new Error("Proposals are drafted only for qualified leads");
  const ev = evidenceIds ?? (lead.evidence || []).map((e) => e.id).filter(Boolean);
  const sam = lead.sam;
  const field = (value, unit) => (value === undefined || value === null ? { value: "UNKNOWN", unit: null, evidenceIds: [] } : { value, unit, evidenceIds: ev });
  const paybackNote =
    sam && "paybackYears" in sam && sam.paybackYears === null
      ? "Payback is not reached under the modeled revenue; no payback figure is quoted."
      : sam?.paybackYears == null
      ? "Payback is UNKNOWN: no load/tariff evidence, so no verified bill savings are claimed."
      : null;
  return {
    status: "DRAFT",
    createdAt: now.toISOString(),
    preliminary: true,
    title: `Preliminary solar proposal - ${lead.lead?.organization || lead.lead?.name || lead.lead?.id}`,
    sections: {
      systemSizeKw: field(sam?.systemSizeKw, "kW"),
      annualKwh: field(sam?.annualKwh, "kWh"),
      installCostUsd: field(sam?.installCostUsd, "USD"),
      paybackYears: field(sam?.paybackYears, "years"),
    },
    paybackNote,
    simulationJobId: sam?.jobId ?? null,
    disclosure: "Preliminary and model-based. Figures depend on the cited evidence and assumptions and are not a guarantee of performance.",
    edits: [],
    approvedBy: null,
    approvedAt: null,
    sentAt: null,
  };
}

export function editProposal(proposal, patch, actor, now = new Date()) {
  if (proposal.status === "SENT") throw new Error("A sent proposal cannot be edited");
  const next = { ...proposal, sections: { ...proposal.sections }, edits: [...proposal.edits] };
  for (const [k, v] of Object.entries(patch.sections || {})) {
    next.sections[k] = { ...(next.sections[k] || {}), value: v, evidenceIds: next.sections[k]?.evidenceIds || [], editedBy: actor };
  }
  if (typeof patch.title === "string") next.title = patch.title;
  next.edits.push({ by: actor, at: now.toISOString() });
  // Any edit voids an earlier approval: the admin approves exactly what is sent.
  next.status = "DRAFT";
  next.approvedBy = null;
  next.approvedAt = null;
  return next;
}

export function approveProposal(proposal, actor, now = new Date()) {
  if (proposal.status !== "DRAFT") throw new Error(`Cannot approve a ${proposal.status} proposal`);
  return { ...proposal, status: "APPROVED", approvedBy: actor, approvedAt: now.toISOString() };
}

export function sendProposal(proposal, actor, now = new Date()) {
  if (proposal.status !== "APPROVED" || !proposal.approvedBy) throw new Error("Only an approved proposal can be sent");
  return { ...proposal, status: "SENT", sentAt: now.toISOString(), sentBy: actor, delivery: "RECORDED_ONLY" };
}

const DAY = 86400000;

// Follow-ups due for a SENT proposal. AUTO -> READY; APPROVAL_GATED ->
// AWAITING_APPROVAL until its template id is in approvedIds.
export function dueFollowUps(proposal, followUpConfig, { now = new Date(), approvedIds = [], doneIds = [] } = {}) {
  if (proposal?.status !== "SENT") return [];
  const sent = Date.parse(proposal.sentAt);
  return followUpConfig.templates
    .filter((t) => !doneIds.includes(t.id) && now.getTime() >= sent + t.afterDays * DAY)
    .map((t) => ({
      templateId: t.id,
      subject: t.subject,
      body: t.body,
      dueAt: new Date(sent + t.afterDays * DAY).toISOString(),
      state: followUpConfig.mode === "AUTO" || approvedIds.includes(t.id) ? "READY" : "AWAITING_APPROVAL",
    }));
}

export function stalledRecommendation(workflow, stalledConfig, now = new Date()) {
  const last = Date.parse(workflow?.updatedAt || workflow?.createdAt || "");
  if (!Number.isFinite(last)) return null;
  const idleDays = Math.floor((now.getTime() - last) / DAY);
  if (idleDays < stalledConfig.afterDays) return null;
  return { idleDays, recommendation: "REASSIGN", autoReassign: !!stalledConfig.autoReassign, currentOwner: workflow.owner ?? null };
}
