// WP6 (T-af486971): root location app as a Lead Intel enrichment adapter.
//
// After a record has been QUALIFIED and an admin has switched "authorize
// analysis" on, this calls the root location app's
// GET /api/prospecting/evaluate (foot traffic, Street View, Google Solar) and
// stores what comes back as Evidence (kind "enrichment") on the record.
//
// Rules (Q36, task body):
//  - never runs on scrape: only on records already qualified, and only while
//    isAnalysisAuthorized() is true (default false);
//  - respects the location app's kill-switches and quota circuit breakers: it
//    makes one call per record, never retries, and treats any refusal
//    (feature disabled, quota hit, HTTP error, timeout, no key) as an explicit
//    "unavailable" status;
//  - never fabricates: unavailable sections get an evidence entry that says so
//    and carries no measurements;
//  - never leaks keys: the location app's Street View image URLs embed the
//    Maps API key, so only the pano id, date and headings are kept;
//  - never touches qualification fields: it only appends to evidence[].
//
// Built by Claude Sonnet 5.5, Lead Intelligence Platform.
const { createEvidence, mergeEvidence } = require("../qualification/evidence");
const { recordKey } = require("../qualification/duplicates");
const { isAnalysisAuthorized } = require("./analysis-authorization");

const DEFAULT_BASE_URL = process.env.LOCATION_APP_URL || "http://localhost:3000";
const DEFAULT_TIMEOUT_MS = 15000;
const CAPTURED_BY = "engine:location-enrichment";

/** Default client: single GET, no retries, never throws. */
function createHttpEvaluateClient({ baseUrl = DEFAULT_BASE_URL, timeoutMs = DEFAULT_TIMEOUT_MS, fetchImpl = globalThis.fetch } = {}) {
  return async function evaluate(lat, lng) {
    if (typeof fetchImpl !== "function") return { ok: false, reason: "no fetch available" };
    const url = `${String(baseUrl).replace(/\/$/, "")}/api/prospecting/evaluate?lat=${encodeURIComponent(lat)}&lng=${encodeURIComponent(lng)}`;
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), timeoutMs);
    try {
      const res = await fetchImpl(url, { signal: ctrl.signal });
      let body = null;
      try { body = await res.json(); } catch { /* non-JSON body */ }
      if (!res.ok || !body || body.success !== true || !body.data) {
        return { ok: false, reason: (body && body.error) || `HTTP ${res.status}` };
      }
      return { ok: true, data: body.data };
    } catch (err) {
      return { ok: false, reason: err && err.name === "AbortError" ? "timeout" : String((err && err.message) || err) };
    } finally {
      clearTimeout(timer);
    }
  };
}

function toNumber(v) {
  const n = typeof v === "string" && v.trim() !== "" ? Number(v) : v;
  return typeof n === "number" && Number.isFinite(n) ? n : null;
}

/** @returns {{lat:number,lng:number}|null} */
function coordinatesOf(record) {
  const loc = record.location && typeof record.location === "object" ? record.location : {};
  const lat = toNumber(record.latitude ?? record.lat ?? loc.lat ?? loc.latitude);
  const lng = toNumber(record.longitude ?? record.lng ?? record.lon ?? loc.lng ?? loc.lon ?? loc.longitude);
  if (lat === null || lng === null || lat < -90 || lat > 90 || lng < -180 || lng > 180) return null;
  return { lat, lng };
}

function isQualifiedRecord(record) {
  return Boolean(record) && (record.qualification_status === "qualified" || record.status === "qualified");
}

/** Pulls only the measurements, dropping anything key-bearing. */
function sectionObservation(name, section) {
  if (!section || typeof section !== "object") return { available: false, reason: "not returned" };
  if (name === "foot_traffic") {
    if (typeof section.footTrafficScore !== "number") return { available: false, reason: "no score returned" };
    return {
      available: true,
      foot_traffic_score: section.footTrafficScore,
      commercial_density: section.commercialDensity ?? null,
      transit_hubs: section.transitHubs ?? null,
      total_reviews_in_radius: section.totalReviewsInRadius ?? null,
    };
  }
  if (section.available !== true) return { available: false, reason: section.message || section.status || "unavailable" };
  if (name === "street_view") {
    return {
      available: true,
      pano_id: section.panoId ?? null,
      imagery_date: section.date ?? null,
      headings: Array.isArray(section.images) ? section.images.map((i) => i.heading).filter((h) => typeof h === "number") : [],
    };
  }
  return {
    available: true,
    max_panels: section.maxPanelsCount ?? null,
    roof_area_m2: section.roofAreaM2 ?? null,
    sunshine_hours_per_year: section.sunshineHoursPerYear ?? null,
    panel_capacity_watts: section.panelCapacityWatts ?? null,
  };
}

const SECTIONS = [
  ["foot_traffic", "traffic"],
  ["street_view", "visual"],
  ["solar", "solar"],
];

/**
 * Enriches one qualified Opportunity. Never throws for an unavailable
 * service; refusals come back as `status`.
 *
 * @param {object} record persisted Opportunity row
 * @param {{ evaluate?: Function, now?: Date, isAuthorized?: never }} [opts]
 * @returns {Promise<{ status: "enriched"|"partial"|"unavailable"|"not_authorized"|"not_qualified"|"no_coordinates", record: object, evidence: object[], reason?: string }>}
 */
async function enrichOpportunity(record, opts = {}) {
  const refuse = (status, reason) => ({ status, record, evidence: [], reason });
  if (!record || typeof record !== "object") return refuse("not_qualified", "no record");
  // The flag is read from the module-private store; there is no option to override it.
  if (!isAnalysisAuthorized()) return refuse("not_authorized", "analysis is not authorized by an admin");
  if (record.type === "lead" || record.record_family === "contact_lead") {
    return refuse("not_qualified", "enrichment applies to Opportunity records only");
  }
  if (!isQualifiedRecord(record)) return refuse("not_qualified", "record has not been qualified");
  const coords = coordinatesOf(record);
  if (!coords) return refuse("no_coordinates", "record has no usable coordinates");

  const now = opts.now || new Date();
  const evaluate = opts.evaluate || createHttpEvaluateClient();
  const key = record.key || recordKey(record);
  const make = (rule, outcome, observed, note) =>
    createEvidence({
      opportunity_key: key,
      kind: "enrichment",
      rule,
      outcome,
      observed,
      note,
      source_url: "location-app:/api/prospecting/evaluate",
      captured_by: CAPTURED_BY,
      is_synthetic: false,
      now,
    });

  let result;
  try {
    result = await evaluate(coords.lat, coords.lng);
  } catch (err) {
    result = { ok: false, reason: String((err && err.message) || err) };
  }

  if (!result || result.ok !== true || !result.data) {
    const reason = (result && result.reason) || "no response";
    const ev = [make("LOCATION_ENRICHMENT_UNAVAILABLE", "info", { available: false, reason, coordinates: coords }, `location app unavailable: ${reason}`)];
    return { status: "unavailable", record: { ...record, evidence: mergeEvidence(record.evidence, ev) }, evidence: ev, reason };
  }

  const ev = [];
  let available = 0;
  for (const [name, field] of SECTIONS) {
    const obs = sectionObservation(name, result.data[field]);
    if (obs.available) available += 1;
    ev.push(make(`LOCATION_${name.toUpperCase()}`, obs.available ? "info" : "info", { ...obs, coordinates: coords }, obs.available ? null : `${name} unavailable: ${obs.reason}`));
  }
  const status = available === SECTIONS.length ? "enriched" : available === 0 ? "unavailable" : "partial";
  return { status, record: { ...record, evidence: mergeEvidence(record.evidence, ev) }, evidence: ev };
}

/**
 * Sequential batch (one location-app call per record, in order, so the
 * location app's quota breaker is never hit by a burst). Stops early once
 * the service reports unavailable, to avoid hammering a tripped breaker.
 */
async function enrichQualifiedBatch(records, opts = {}) {
  const out = [];
  let stopped = false;
  for (const record of records || []) {
    if (stopped) {
      out.push({ status: "skipped", record, evidence: [], reason: "location app unavailable earlier in this batch" });
      continue;
    }
    const r = await enrichOpportunity(record, opts);
    out.push(r);
    if (r.status === "unavailable") stopped = true;
    if (r.status === "not_authorized") stopped = true;
  }
  return out;
}

module.exports = { enrichOpportunity, enrichQualifiedBatch, createHttpEvaluateClient, coordinatesOf };
