'use strict';
/**
 * Merchandise POS (T-52a68d25). Nonregulated merchandise only; mock POS.
 * - Inventory ledger mirrors commerce InventoryItem / Reservation / InventoryMovement.
 * - Payment adapter registry: unknown/unconfigured providers fall back to mock.
 * - Offline queue: sales taken offline are reserved locally and flushed on reconnect.
 * - 280E separation: restricted (cannabis) SKUs are rejected; no canna data is read.
 */
class InventoryLedger {
  constructor() { this.items = new Map(); this.reservations = new Map(); this.movements = []; this._n = 0; }
  addItem(sku, onHand) {
    if (!Number.isInteger(onHand) || onHand < 0) throw new Error('onHand must be non-negative integer');
    this.items.set(sku, { sku, onHand, reserved: 0 }); this._mv(sku, 'RECEIVE', onHand);
  }
  _mv(sku, type, qty, ref) { this.movements.push({ id: ++this._n, sku, type, qty, ref: ref || null }); }
  available(sku) { const i = this.items.get(sku); return i ? i.onHand - i.reserved : 0; }
  reserve(id, lines) {
    for (const l of lines) if (this.available(l.sku) < l.qty) throw new Error(`insufficient stock: ${l.sku}`);
    for (const l of lines) { this.items.get(l.sku).reserved += l.qty; this._mv(l.sku, 'RESERVE', l.qty, id); }
    this.reservations.set(id, { id, lines, status: 'HELD' });
  }
  commit(id) {
    const r = this.reservations.get(id); if (!r || r.status !== 'HELD') throw new Error('no held reservation');
    for (const l of r.lines) { const it = this.items.get(l.sku); it.reserved -= l.qty; it.onHand -= l.qty; this._mv(l.sku, 'SALE', -l.qty, id); }
    r.status = 'COMMITTED';
  }
  release(id) {
    const r = this.reservations.get(id); if (!r || r.status !== 'HELD') return;
    for (const l of r.lines) { this.items.get(l.sku).reserved -= l.qty; this._mv(l.sku, 'RELEASE', l.qty, id); }
    r.status = 'RELEASED';
  }
}

class PaymentRegistry {
  constructor() { this.adapters = new Map(); this.register('mock', { charge: async (cents, ref) => ({ ok: true, provider: 'mock', ref }) }); }
  register(name, adapter) { this.adapters.set(name, adapter); }
  get(name) { return this.adapters.get(name) || this.adapters.get('mock'); }
}

class MerchPos {
  constructor({ ledger = new InventoryLedger(), payments = new PaymentRegistry(), catalog = {}, now = Date.now } = {}) {
    this.ledger = ledger; this.payments = payments; this.catalog = new Map(Object.entries(catalog));
    this.now = now; this.online = true; this.queue = []; this.orders = new Map(); this._n = 0;
  }
  setCatalogItem(sku, { name, priceCents, restricted = false }) {
    if (!Number.isInteger(priceCents) || priceCents < 0) throw new Error('integer cents required');
    this.catalog.set(sku, { sku, name, priceCents, restricted });
  }
  setOnline(v) { this.online = !!v; }
  _total(lines) {
    let t = 0;
    for (const l of lines) {
      const c = this.catalog.get(l.sku); if (!c) throw new Error(`unknown sku: ${l.sku}`);
      if (c.restricted) throw new Error(`restricted item not sold via merchandise POS: ${l.sku}`);
      if (!Number.isInteger(l.qty) || l.qty < 1) throw new Error('qty must be positive integer');
      t += c.priceCents * l.qty;
    }
    return t;
  }
  async sale({ lines, provider = 'mock' }) {
    const totalCents = this._total(lines); const id = `S${++this._n}`;
    this.ledger.reserve(id, lines);
    const order = { id, lines, totalCents, provider, status: 'PENDING', createdAt: this.now() };
    this.orders.set(id, order);
    if (!this.online) { order.status = 'QUEUED_OFFLINE'; this.queue.push(id); return order; }
    return this._settle(order);
  }
  async _settle(order) {
    try {
      const r = await this.payments.get(order.provider).charge(order.totalCents, order.id);
      if (!r.ok) throw new Error('declined');
      this.ledger.commit(order.id); order.status = 'PAID'; order.payment = r;
    } catch (e) { this.ledger.release(order.id); order.status = 'FAILED'; order.error = e.message; }
    return order;
  }
  async reconnect() {
    this.online = true; const out = [];
    while (this.queue.length) { const o = this.orders.get(this.queue.shift()); out.push(await this._settle(o)); }
    return out;
  }
  async refund(id) {
    const o = this.orders.get(id); if (!o || o.status !== 'PAID') throw new Error('only paid orders refundable');
    for (const l of o.lines) { this.ledger.items.get(l.sku).onHand += l.qty; this.ledger._mv(l.sku, 'RETURN', l.qty, id); }
    o.status = 'REFUNDED'; return o;
  }
  report() {
    const paid = [...this.orders.values()].filter((o) => o.status === 'PAID');
    return { paidCount: paid.length, grossCents: paid.reduce((s, o) => s + o.totalCents, 0), queued: this.queue.length };
  }
}
module.exports = { InventoryLedger, PaymentRegistry, MerchPos };
