/**
 * Event Manager - Festival POS Integration (pm T-c8ca10a8, parent).
 * One interface over the child pieces: MenuSync (catalog/menu push) and Reconciliation (post-event
 * inventory vs POS sales). Each location is bound to a ledger (regulated | merchandise) and a driver
 * (sandbox/mock Dutchie, Treez, merchandise POS) exposing { pushMenu(items), pushOrder?(order), fetchSales?(eventId) }.
 * Interface: syncCatalog / syncInventory / pushOrder / reconcile / settlementAllowed.
 */
'use strict';
const { MenuSync } = require('./menu-sync.cjs');
const { Reconciliation, LEDGERS } = require('./reconciliation.cjs');

class PosIntegration {
  constructor({ menuOpts = {}, reconciliation = new Reconciliation(), ageGate = 21 } = {}) {
    this.drivers = {}; this.ledgerOf = new Map(); this.ageGate = ageGate;
    this.menu = new MenuSync({ ...menuOpts, pos: this.drivers });
    this.recon = reconciliation;
    this.orders = [];
  }
  /** Bind a location to a ledger and a POS driver. */
  registerLocation(loc, { ledger, driver, brands }) {
    if (!LEDGERS.includes(ledger)) throw new Error(`ledger must be ${LEDGERS.join('|')}`);
    if (!driver || typeof driver.pushMenu !== 'function') throw new Error('driver.pushMenu required');
    this.drivers[loc] = driver; this.ledgerOf.set(loc, ledger);
    if (brands) this.menu.setLocationBrands(loc, brands);
  }
  /** Catalog: set company products, then push menus to one or all locations. */
  async syncCatalog(products = [], loc = null) {
    for (const p of products) this.menu.setProduct(p);
    return loc ? { [loc]: await this.menu.sync(loc) } : this.menu.syncAll();
  }
  /** Inventory: set stock levels then re-push (out-of-stock reflected on POS). */
  async syncInventory(loc, stock = {}) {
    for (const [sku, qty] of Object.entries(stock)) this.menu.setStock(loc, sku, qty);
    return this.menu.sync(loc);
  }
  /** Order push: validates stock, 21+ gate on regulated items, ledger routing; decrements stock on success. */
  async pushOrder(loc, order) {
    const driver = this.drivers[loc]; if (!driver) throw new Error(`no POS driver for ${loc}`);
    const ledger = this.ledgerOf.get(loc);
    const lines = order.lines || []; if (!lines.length) throw new Error('order has no lines');
    for (const l of lines) {
      const p = this.menu.catalog.get(l.sku); if (!p) throw new Error(`unknown sku ${l.sku}`);
      if (!Number.isInteger(l.qty) || l.qty < 1) throw new Error('qty must be integer >= 1');
      if (p.restricted && ledger !== 'regulated') throw new Error(`restricted sku ${l.sku} cannot sell on ${ledger} ledger`);
      if (p.restricted && !(order.customerAge >= this.ageGate)) throw new Error(`${this.ageGate}+ verification required for ${l.sku}`);
      const k = `${loc}|${l.sku}`;
      if (this.menu.pulled.has(k) || (this.menu.stock.get(k) || 0) < l.qty) throw new Error(`out of stock: ${l.sku}`);
    }
    const priced = lines.map((l) => ({ ...l, unitCents: this.menu.build(loc).find((i) => i.sku === l.sku).priceCents }));
    const payload = { ...order, loc, ledger, lines: priced, totalCents: priced.reduce((s, l) => s + l.qty * l.unitCents, 0) };
    if (typeof driver.pushOrder !== 'function') throw new Error('driver does not support pushOrder');
    try { await driver.pushOrder(payload); } catch (e) { return { ok: false, error: String(e.message || e) }; }
    for (const l of lines) { const k = `${loc}|${l.sku}`; this.menu.stock.set(k, this.menu.stock.get(k) - l.qty); }
    this.orders.push(payload);
    return { ok: true, totalCents: payload.totalCents, ledger };
  }
  /** Reconcile a ledger; if inputs lack posReports, fetch sales from that ledger's drivers. */
  async reconcile(eventId, ledger, input = {}) {
    let posReports = input.posReports;
    if (!posReports) {
      posReports = [];
      for (const [loc, l] of this.ledgerOf) {
        const d = this.drivers[loc];
        if (l === ledger && typeof d.fetchSales === 'function') posReports.push(...await d.fetchSales(eventId));
      }
    }
    return this.recon.run({ ...input, eventId, ledger, posReports });
  }
  settlementAllowed(eventId, ledgers) { return this.recon.settlementAllowed(eventId, ledgers); }
  screen(loc, opts) { return this.menu.screen(loc, opts); }
}

module.exports = { PosIntegration };
