/**
 * Event Manager - Regulated POS connectivity (pm T-52dbfab5, Q23/Q51, locked Q20).
 * One interface over Dutchie/Treez-style drivers: syncCatalog, syncInventory, pushOrder.
 * Cannabis is browse-only on the web and sold only through the licensed POS. Metrc track-and-trace
 * stays in canna (not modelled here). Drivers are injected (sandbox/mock only; no real credentials).
 * Compliance gates are enforced from real inputs, never hard-coded (cf. canna checkout route bug).
 * CSV fallback parses a POS export when no API access exists (E8).
 */
'use strict';

const DRIVER_METHODS = ['syncCatalog', 'syncInventory', 'pushOrder'];
const SELL_ROLES = Object.freeze(['budtender', 'manager', 'admin']);

function assertDriver(name, d) {
  for (const m of DRIVER_METHODS) if (!d || typeof d[m] !== 'function') throw new Error(`driver ${name} missing ${m}`);
}

class RegulatedPos {
  constructor({ drivers = {}, now = () => Date.now(), ageGate = 21 } = {}) {
    for (const [n, d] of Object.entries(drivers)) assertDriver(n, d);
    this.drivers = drivers; this.now = now; this.ageGate = ageGate;
    this.licences = new Map(); // locationId -> {driver, licenceNo, expiresAt, verified}
    this.catalog = new Map(); this.inventory = new Map(); this.orders = []; this.audit = [];
  }
  registerLocation(loc, { driver, licenceNo, expiresAt, verified }) {
    if (!this.drivers[driver]) throw new Error(`unknown driver ${driver}`);
    this.licences.set(loc, { driver, licenceNo, expiresAt, verified: verified === true });
  }
  _licenceOk(loc) {
    const l = this.licences.get(loc);
    if (!l) return { ok: false, reason: 'no_licence_on_file' };
    if (!l.verified || !l.licenceNo) return { ok: false, reason: 'licence_unverified' };
    if (l.expiresAt != null && l.expiresAt <= this.now()) return { ok: false, reason: 'licence_expired' };
    return { ok: true, l };
  }
  _drv(loc) { const c = this._licenceOk(loc); if (!c.ok) throw Object.assign(new Error(c.reason), { code: c.reason }); return this.drivers[c.l.driver]; }

  async syncCatalog(loc) {
    const items = await this._drv(loc).syncCatalog(loc);
    this.catalog.set(loc, items.map((i) => ({ sku: i.sku, name: i.name, priceCents: i.priceCents, thcMg: i.thcMg ?? null })));
    return this.catalog.get(loc);
  }
  async syncInventory(loc) {
    const rows = await this._drv(loc).syncInventory(loc);
    const m = new Map(rows.map((r) => [r.sku, r.qty])); this.inventory.set(loc, m); return m;
  }
  /** Web storefront view: browse only, no price-to-cart, no purchase path (Q20). */
  browse(loc) {
    return (this.catalog.get(loc) || []).map((i) => ({ ...i, purchasable: false, channel: 'browse_only', soldAt: 'licensed_pos' }));
  }
  /** Web checkout attempt for cannabis: always refused. */
  webCheckout() { throw Object.assign(new Error('cannabis is browse-only online; sale occurs at the licensed POS'), { code: 'browse_only' }); }

  /**
   * order: {id, loc, items:[{sku,qty}], customer:{dob, idVerified}, actor:{id, role, twoFactor}}
   * All gates read real inputs: role, 2FA, licence, age from DOB, ID check, stock.
   */
  async pushOrder(order) {
    const fail = (code) => { this.audit.push({ a: 'refused', id: order.id, code, at: this.now() }); throw Object.assign(new Error(code), { code }); };
    const { actor = {}, customer = {}, loc } = order;
    if (!SELL_ROLES.includes(actor.role)) fail('role_not_permitted');
    if (actor.twoFactor !== true) fail('two_factor_required');
    const lc = this._licenceOk(loc); if (!lc.ok) fail(lc.reason);
    if (customer.idVerified !== true) fail('id_not_verified');
    if (!(customer.dob > 0) || this._age(customer.dob) < this.ageGate) fail('under_age');
    if (!order.items || !order.items.length) fail('empty_order');
    const stock = this.inventory.get(loc) || new Map();
    for (const it of order.items) {
      if (!Number.isInteger(it.qty) || it.qty < 1) fail('bad_qty');
      if ((stock.get(it.sku) ?? 0) < it.qty) fail(`out_of_stock:${it.sku}`);
    }
    const res = await this.drivers[lc.l.driver].pushOrder(order);
    for (const it of order.items) stock.set(it.sku, stock.get(it.sku) - it.qty);
    this.orders.push({ id: order.id, loc, posRef: res && res.ref, at: this.now() });
    this.audit.push({ a: 'sold', id: order.id, by: actor.id, at: this.now() });
    return { id: order.id, posRef: res && res.ref };
  }
  _age(dob) { return Math.floor((this.now() - dob) / (365.25 * 86400000)); }
}

/** CSV fallback: "sku,name,price,qty" with header; returns {catalog, inventory, errors}. */
function parsePosCsv(text) {
  const lines = String(text).split(/\r?\n/).filter((l) => l.trim());
  const head = (lines.shift() || '').split(',').map((s) => s.trim().toLowerCase());
  const ix = Object.fromEntries(['sku', 'name', 'price', 'qty'].map((k) => [k, head.indexOf(k)]));
  if (Object.values(ix).some((v) => v < 0)) throw new Error('csv header must contain sku,name,price,qty');
  const catalog = [], inventory = [], errors = [];
  lines.forEach((ln, n) => {
    const c = ln.split(',').map((s) => s.trim());
    const price = Math.round(parseFloat(c[ix.price]) * 100), qty = Number(c[ix.qty]);
    if (!c[ix.sku] || !Number.isFinite(price) || price < 0 || !Number.isInteger(qty) || qty < 0) { errors.push({ row: n + 2, line: ln }); return; }
    catalog.push({ sku: c[ix.sku], name: c[ix.name], priceCents: price }); inventory.push({ sku: c[ix.sku], qty });
  });
  return { catalog, inventory, errors };
}

/** Mock driver for tests/sandbox. */
function mockDriver({ catalog = [], inventory = [], fail = false } = {}) {
  const pushed = [];
  return {
    pushed,
    syncCatalog: async () => { if (fail) throw new Error('POS down'); return catalog; },
    syncInventory: async () => inventory,
    pushOrder: async (o) => { if (fail) throw new Error('POS down'); pushed.push(o); return { ref: `POS-${pushed.length}` }; },
  };
}

module.exports = { RegulatedPos, parsePosCsv, mockDriver, SELL_ROLES };
