/**
 * Event Manager - Workstream E (pm T-5e6cfae1): company-collected event fees, processor selection,
 * tax, licence/age/jurisdiction gates and per-event accounting. Processors are mocked adapters;
 * this module moves no real money. Eligibility is data (models.ProcessorEligibility) with evidence.
 * Cannabis-related fees can never use Stripe (hard reject), and tax rates are configured data.
 */
'use strict';
const { isProcessorAllowed } = require('./models.cjs');

const FEE_TYPES = Object.freeze(['ticket', 'booth', 'sponsor', 'merchandise']);
const PROCESSORS = Object.freeze(['stripe', 'paymongo', 'crypto', 'ach', 'invoice']);
const OFFLINE = Object.freeze(['invoice']); // E9: offline invoicing needs no eligibility row
const CANNABIS_BLOCKED = Object.freeze(['stripe']);

/** Mock processor adapter: records charges, never calls a network. */
class MockProcessor {
  constructor(name) { this.name = name; this.charges = []; }
  charge({ feeId, cents }) { const c = { id: `${this.name}-${this.charges.length + 1}`, feeId, cents }; this.charges.push(c); return c; }
}

/** Tax: rules are data [{id, kind: 'excise'|'sales'|'local', bp, appliesTo: [feeType], jurisdiction, cannabisOnly}]. */
function calcTax(rules, { feeType, jurisdiction, cents, cannabis = false }) {
  const lines = [];
  for (const r of rules) {
    if (r.jurisdiction !== jurisdiction) continue;
    if (r.appliesTo && !r.appliesTo.includes(feeType)) continue;
    if (r.cannabisOnly && !cannabis) continue;
    lines.push({ id: r.id, kind: r.kind, cents: Math.round((cents * r.bp) / 10000) });
  }
  return { lines, totalCents: lines.reduce((s, l) => s + l.cents, 0) };
}

/** Age 21+ and jurisdiction rule engine. */
function checkAgeJurisdiction({ birthDate, onDate, jurisdiction, allowedJurisdictions }) {
  const fails = [];
  const b = new Date(birthDate), d = new Date(onDate);
  let age = d.getUTCFullYear() - b.getUTCFullYear();
  if (d.getUTCMonth() < b.getUTCMonth() || (d.getUTCMonth() === b.getUTCMonth() && d.getUTCDate() < b.getUTCDate())) age--;
  if (Number.isNaN(age) || age < 21) fails.push('under 21');
  if (!allowedJurisdictions.includes(jurisdiction)) fails.push('jurisdiction not permitted');
  return { ok: fails.length === 0, failures: fails };
}

/** Licence check: operator must hold an active, unexpired licence in the jurisdiction with a clear compliance record. */
function checkLicense({ license, compliance = [], jurisdiction, onDate }) {
  const fails = [];
  if (!license) fails.push('no licence');
  else {
    if (license.status !== 'active') fails.push('licence not active');
    if (license.jurisdiction !== jurisdiction) fails.push('licence jurisdiction mismatch');
    if (license.expiresOn && license.expiresOn < onDate) fails.push('licence expired');
  }
  if (compliance.some((c) => c.status === 'open_violation')) fails.push('open compliance violation');
  return { ok: fails.length === 0, failures: fails };
}

class FeeLedger {
  /** eligibility: ProcessorEligibility rows; taxRules; processors: {name: adapter}. */
  constructor({ eligibility = [], taxRules = [], processors = {}, now = () => new Date().toISOString() } = {}) {
    this.eligibility = eligibility; this.taxRules = taxRules; this.now = now;
    this.processors = { ...Object.fromEntries(PROCESSORS.map((p) => [p, new MockProcessor(p)])), ...processors };
    this.selection = new Map(); // `${eventId}|${feeType}` or `*|${feeType}`
    this.fees = new Map(); this.costs = [];
  }
  selectProcessor({ eventId = '*', feeType, processor }) {
    if (!FEE_TYPES.includes(feeType)) throw new Error('invalid feeType');
    if (!PROCESSORS.includes(processor)) throw new Error('invalid processor');
    this.selection.set(`${eventId}|${feeType}`, processor);
  }
  processorFor(eventId, feeType) { return this.selection.get(`${eventId}|${feeType}`) || this.selection.get(`*|${feeType}`) || null; }

  /** Decide whether a fee may be collected through its processor. */
  evaluate({ event, feeType, cannabis = false }) {
    const processor = this.processorFor(event.id, feeType);
    if (!processor) return { ok: false, processor: null, reason: 'no processor selected' };
    if (cannabis && CANNABIS_BLOCKED.includes(processor)) return { ok: false, processor, reason: 'stripe rejected for cannabis' };
    if (OFFLINE.includes(processor)) return { ok: true, processor, offline: true };
    if (!isProcessorAllowed(this.eligibility, { processor, feeType, eventType: event.type, jurisdiction: event.jurisdiction }))
      return { ok: false, processor, reason: 'processor not approved' };
    return { ok: true, processor };
  }

  /** Charge a fee: gates, tax, then mock processor (or offline invoice record). */
  collect({ event, feeId, feeType, cents, cannabis = false, payer, licenseCheck, ageCheck }) {
    if (!FEE_TYPES.includes(feeType)) throw new Error('invalid feeType');
    if (!Number.isInteger(cents) || cents < 0) throw new Error('cents must be non-negative integer');
    if (this.fees.has(feeId)) throw new Error('duplicate feeId');
    if (cannabis && licenseCheck && !licenseCheck.ok) throw new Error(`licence gate: ${licenseCheck.failures.join('; ')}`);
    if (ageCheck && !ageCheck.ok) throw new Error(`age gate: ${ageCheck.failures.join('; ')}`);
    const ev = this.evaluate({ event, feeType, cannabis });
    if (!ev.ok) throw new Error(ev.reason);
    const tax = calcTax(this.taxRules, { feeType, jurisdiction: event.jurisdiction, cents, cannabis });
    const total = cents + tax.totalCents;
    const charge = ev.offline ? { id: `inv-${feeId}`, feeId, cents: total, offline: true } : this.processors[ev.processor].charge({ feeId, cents: total });
    const fee = { feeId, eventId: event.id, feeType, payer, cents, taxCents: tax.totalCents, taxLines: tax.lines, totalCents: total,
      processor: ev.processor, status: ev.offline ? 'invoiced' : 'paid', chargeId: charge.id, at: this.now() };
    this.fees.set(feeId, fee);
    return fee;
  }
  markInvoicePaid(feeId) { const f = this.fees.get(feeId); if (!f || f.status !== 'invoiced') throw new Error('not an open invoice'); f.status = 'paid'; return f; }
  addCost({ eventId, description, cents }) { this.costs.push({ eventId, description, cents }); }

  /** Per-event accounting and profitability. Invoiced fees are receivable, not revenue. */
  report(eventId) {
    const fees = [...this.fees.values()].filter((f) => f.eventId === eventId);
    const byType = {};
    for (const f of fees) { byType[f.feeType] = (byType[f.feeType] || 0) + f.cents; }
    const sum = (arr, k) => arr.reduce((s, x) => s + x[k], 0);
    const paid = fees.filter((f) => f.status === 'paid'), open = fees.filter((f) => f.status === 'invoiced');
    const revenue = sum(paid, 'cents'), taxCollected = sum(paid, 'taxCents');
    const costs = sum(this.costs.filter((c) => c.eventId === eventId), 'cents');
    const profit = revenue - costs;
    return { eventId, byType, revenueCents: revenue, taxCollectedCents: taxCollected, receivableCents: sum(open, 'totalCents'),
      costsCents: costs, profitCents: profit, marginBp: revenue ? Math.round((profit * 10000) / revenue) : null };
  }
}

module.exports = { FEE_TYPES, PROCESSORS, MockProcessor, calcTax, checkAgeJurisdiction, checkLicense, FeeLedger };
