/**
 * Event Manager - Merchandise POS (pm T-52a68d25). Nonregulated merchandise only (no restricted/age-gated SKUs).
 * Mock POS: stock uses an injected inventory ledger (reserve -> commit/release movements, mirroring
 * commerce InventoryItem/Reservation/InventoryMovement), payments via an injected adapter (mock default).
 * Offline: sales queue locally with idempotency keys and replay on reconnect. No canna data (280E separation).
 */
'use strict';

class MockLedger {
  constructor(stock = {}) { this.stock = { ...stock }; this.reserved = {}; this.movements = []; }
  available(sku) { return (this.stock[sku] || 0) - (this.reserved[sku] || 0); }
  reserve(sku, qty) {
    if (this.available(sku) < qty) throw new Error(`insufficient stock: ${sku}`);
    this.reserved[sku] = (this.reserved[sku] || 0) + qty; this.movements.push({ type: 'reserve', sku, qty });
  }
  release(sku, qty) { this.reserved[sku] -= qty; this.movements.push({ type: 'release', sku, qty }); }
  commit(sku, qty) { this.reserved[sku] -= qty; this.stock[sku] -= qty; this.movements.push({ type: 'sale', sku, qty }); }
}
const mockPayments = { charge: async ({ amountCents, key }) => ({ id: `mock_${key}`, status: 'paid', amountCents }) };

class MerchPOS {
  constructor({ ledger, catalog = {}, payments = mockPayments } = {}) {
    this.ledger = ledger; this.catalog = catalog; this.payments = payments;
    this.online = true; this.queue = []; this.sales = new Map(); this.seq = 0;
  }
  setOnline(v) { this.online = !!v; }
  _price(lines) {
    return lines.reduce((sum, { sku, qty }) => {
      const p = this.catalog[sku];
      if (!p) throw new Error(`unknown sku: ${sku}`);
      if (p.restricted) throw new Error(`restricted item not sold via merch POS: ${sku}`);
      if (!Number.isInteger(qty) || qty < 1) throw new Error('qty must be a positive integer');
      return sum + p.priceCents * qty;
    }, 0);
  }
  async sell({ lines, key = `s${++this.seq}` }) {
    if (this.sales.has(key)) return this.sales.get(key);          // idempotent
    const total = this._price(lines);
    if (!this.online) { // offline: accept against local stock, queue payment
      lines.forEach((l) => this.ledger.reserve(l.sku, l.qty));
      const sale = { key, lines, totalCents: total, status: 'queued' };
      this.queue.push(sale); this.sales.set(key, sale); return sale;
    }
    return this._settle({ key, lines, totalCents: total });
  }
  async _settle(sale) {
    if (!this.sales.has(sale.key) || sale.status !== 'queued') sale.lines.forEach((l) => this.ledger.reserve(l.sku, l.qty));
    try {
      const pay = await this.payments.charge({ amountCents: sale.totalCents, key: sale.key });
      if (pay.status !== 'paid') throw new Error('payment declined');
      sale.lines.forEach((l) => this.ledger.commit(l.sku, l.qty));
      Object.assign(sale, { status: 'paid', paymentId: pay.id });
    } catch (e) {
      sale.lines.forEach((l) => this.ledger.release(l.sku, l.qty));
      Object.assign(sale, { status: 'failed', error: e.message });
    }
    this.sales.set(sale.key, sale); return sale;
  }
  async reconnect() {
    this.online = true; const q = this.queue; this.queue = [];
    for (const s of q) await this._settle(s);
    return q.map((s) => ({ key: s.key, status: s.status }));
  }
}
module.exports = { MerchPOS, MockLedger, mockPayments };
