/**
 * Event Manager - Regulated POS connectivity (pm T-52dbfab5). Mocked: one interface over
 * Dutchie/Treez-style drivers (syncCatalog, syncInventory, pushOrder). Cannabis is browse-only on
 * the web (Q20) and sold only through the licensed POS. Compliance (licence, 2FA, age) is injected
 * and mocked here; never hard-coded true. Metrc stays in canna.
 */
'use strict';

const REQUIRED = ['syncCatalog', 'syncInventory', 'pushOrder'];

class RegulatedPos {
  /** drivers: { dutchie, treez } each implementing REQUIRED. compliance: async (ctx) => {licenceVerified, hasTwoFactor, age} */
  constructor({ drivers = {}, compliance, minAge = 21 } = {}) {
    for (const [n, d] of Object.entries(drivers)) {
      for (const m of REQUIRED) if (typeof d[m] !== 'function') throw new Error(`driver ${n} missing ${m}`);
    }
    if (typeof compliance !== 'function') throw new Error('compliance check required');
    this.drivers = drivers; this.compliance = compliance; this.minAge = minAge;
  }
  _d(name) { const d = this.drivers[name]; if (!d) throw new Error(`unknown POS driver: ${name}`); return d; }
  syncCatalog(name, opts) { return this._d(name).syncCatalog(opts); }
  syncInventory(name, opts) { return this._d(name).syncInventory(opts); }
  /** Web browse view: regulated items are listed but not purchasable online. */
  browse(items) { return items.map((i) => (i.regulated ? { ...i, purchasable: false, channel: 'licensed-pos' } : { ...i, purchasable: true })); }
  /** Order push. Regulated lines need verified licence, 2FA and age gate; otherwise rejected before the driver is called. */
  async pushOrder(name, order, ctx = {}) {
    const d = this._d(name);
    if (!order || !Array.isArray(order.lines) || !order.lines.length) throw new Error('order lines required');
    if (order.lines.some((l) => l.regulated)) {
      const c = await this.compliance(ctx);
      if (!c || c.licenceVerified !== true) return { ok: false, reason: 'licence_unverified' };
      if (c.hasTwoFactor !== true) return { ok: false, reason: 'two_factor_required' };
      if (!Number.isInteger(c.age) || c.age < this.minAge) return { ok: false, reason: 'age_gate' };
    }
    try { return { ok: true, result: await d.pushOrder(order) }; }
    catch (e) { return { ok: false, reason: 'pos_error', error: e.message }; }
  }
}

module.exports = { RegulatedPos };
