/**
 * Event Manager - Workstream E (pm T-5e6cfae1): event fees, processor eligibility, tax, licensing, accounting.
 * Processor eligibility is data with evidence. Cannabis is never eligible for Stripe. Processors are mocks
 * here: this module records the selected processor and moves no money. Tax rates are config data (basis points).
 */
'use strict';

const FEE_TYPES = Object.freeze(['ticket', 'booth', 'sponsor', 'merchandise', 'cannabis']);
const PROCESSORS = Object.freeze(['stripe', 'paymongo', 'crypto', 'ach', 'invoice', 'offline_invoice']);

class ProcessorEligibility {
  constructor() { this.rules = []; }
  /** Add data rule: {processor, feeType, eligible, evidence}. Stripe allowed only with evidence and never for cannabis. */
  add({ processor, feeType, eligible, evidence }) {
    if (!PROCESSORS.includes(processor)) throw new Error(`unknown processor ${processor}`);
    if (!FEE_TYPES.includes(feeType)) throw new Error(`unknown fee type ${feeType}`);
    if (eligible && !evidence) throw new Error('evidence required for an eligible rule');
    if (processor === 'stripe' && feeType === 'cannabis' && eligible) throw new Error('stripe is never eligible for cannabis');
    const r = { processor, feeType, eligible: !!eligible, evidence: evidence || null };
    this.rules.push(r); return r;
  }
  isEligible(processor, feeType) {
    if (processor === 'stripe' && feeType === 'cannabis') return false;
    const r = this.rules.filter((x) => x.processor === processor && x.feeType === feeType).pop();
    return !!(r && r.eligible);
  }
}

class FeeManager {
  /** processorChoice: {feeType, eventId?} -> processor id; eventId-specific choice wins over type default. */
  constructor({ eligibility, now = () => new Date().toISOString() }) {
    if (!eligibility) throw new Error('eligibility required');
    this.elig = eligibility; this.now = now; this.choices = []; this.fees = []; this.taxRates = []; this.licenses = []; this.expenses = [];
  }
  setProcessor({ feeType, eventId = null, processor }) {
    if (!this.elig.isEligible(processor, feeType)) throw new Error(`${processor} not eligible for ${feeType}`);
    this.choices.push({ feeType, eventId, processor }); return processor;
  }
  processorFor(feeType, eventId) {
    const c = this.choices.filter((x) => x.feeType === feeType && x.eventId === eventId).pop()
      || this.choices.filter((x) => x.feeType === feeType && x.eventId === null).pop();
    return c ? c.processor : null;
  }
  /** taxes: [{feeType, kind: 'sales'|'excise'|'local', bp}] */
  setTaxRate({ feeType, kind, bp }) { this.taxRates.push({ feeType, kind, bp }); }
  tax(feeType, cents) {
    const parts = this.taxRates.filter((t) => t.feeType === feeType).map((t) => ({ kind: t.kind, cents: Math.round((cents * t.bp) / 10000) }));
    return { parts, totalCents: parts.reduce((s, p) => s + p.cents, 0) };
  }
  addLicense({ operatorId, jurisdiction, expiresOn, status = 'active' }) { this.licenses.push({ operatorId, jurisdiction, expiresOn, status }); }
  /** Cannabis charge gate: valid licence in jurisdiction on date, buyer 21+. */
  checkCannabis({ operatorId, jurisdiction, date, buyerAge }) {
    const reasons = [];
    const l = this.licenses.find((x) => x.operatorId === operatorId && x.jurisdiction === jurisdiction);
    if (!l) reasons.push('no licence for jurisdiction');
    else { if (l.status !== 'active') reasons.push('licence not active'); if (l.expiresOn < date) reasons.push('licence expired'); }
    if (!(buyerAge >= 21)) reasons.push('buyer under 21 or age unknown');
    return { allowed: reasons.length === 0, reasons };
  }
  charge({ eventId, feeType, payerId, cents, date, operatorId, jurisdiction, buyerAge }) {
    if (!(cents > 0)) throw new Error('cents must be positive');
    if (feeType === 'cannabis') {
      const g = this.checkCannabis({ operatorId, jurisdiction, date, buyerAge });
      if (!g.allowed) throw new Error(`cannabis blocked: ${g.reasons.join('; ')}`);
    }
    const processor = this.processorFor(feeType, eventId);
    if (!processor) throw new Error(`no processor configured for ${feeType}`);
    const t = this.tax(feeType, cents);
    const f = { id: `F-${this.fees.length + 1}`, eventId, feeType, payerId, cents, taxCents: t.totalCents, taxParts: t.parts, processor, at: this.now() };
    this.fees.push(f); return f;
  }
  addExpense({ eventId, description, cents }) { this.expenses.push({ eventId, description, cents }); }
  /** Per-event profitability: revenue, tax collected, expenses, net (revenue - expenses), by fee type. */
  profitability(eventId) {
    const fees = this.fees.filter((f) => f.eventId === eventId);
    const byType = {};
    for (const f of fees) byType[f.feeType] = (byType[f.feeType] || 0) + f.cents;
    const revenueCents = fees.reduce((s, f) => s + f.cents, 0);
    const taxCents = fees.reduce((s, f) => s + f.taxCents, 0);
    const expenseCents = this.expenses.filter((e) => e.eventId === eventId).reduce((s, e) => s + e.cents, 0);
    return { eventId, revenueCents, taxCents, expenseCents, netCents: revenueCents - expenseCents, byType };
  }
}

module.exports = { FEE_TYPES, PROCESSORS, ProcessorEligibility, FeeManager };
EOF
