  markRead(userId: string, ids?: string[]): Promise<number>;
  rules(event: string): Promise<NotificationRuleRow[]>;
  pushSubscriptions(userId: string): Promise<{ endpoint: string; p256dh: string; auth: string }[]>;
}

/** Structural subset of the Prisma client used by the store. */
export interface NotificationPrismaLike {
  notification: {
    create(args: { data: { userId: string; type: string; title: string; body: string } }): Promise<unknown>;
    findMany(args: { where: { userId: string }; orderBy: { createdAt: "desc" }; take: number }): Promise<NotificationRecord[]>;
    count(args: { where: { userId: string; status: "UNREAD" } }): Promise<number>;
    updateMany(args: { where: { userId: string; status: "UNREAD"; id?: { in: string[] } }; data: { status: "READ" } }): Promise<{ count: number }>;
  };
  notificationRule: {
    findMany(args: { where: { event: string } }): Promise<NotificationRuleRow[]>;
  };
  pushSubscription: {
    findMany(args: { where: { userId: string } }): Promise<{ endpoint: string; p256dh: string; auth: string }[]>;
  };
}

export function createPrismaNotificationStore(prisma: NotificationPrismaLike): NotificationStore {
  return {
    async create(userId, n) {
      await prisma.notification.create({ data: { userId, type: n.type, title: n.title, body: n.body } });
    },
    list: (userId, limit = 50) =>
      prisma.notification.findMany({ where: { userId }, orderBy: { createdAt: "desc" }, take: limit }),
    unreadCount: (userId) => prisma.notification.count({ where: { userId, status: "UNREAD" } }),
    async markRead(userId, ids) {
      const where: { userId: string; status: "UNREAD"; id?: { in: string[] } } = { userId, status: "UNREAD" };
      if (ids) where.id = { in: ids };
      return (await prisma.notification.updateMany({ where, data: { status: "READ" } })).count;
    },
    rules: (event) => prisma.notificationRule.findMany({ where: { event } }),
    pushSubscriptions: (userId) => prisma.pushSubscription.findMany({ where: { userId } }),
  };
}

export interface ExtraChannels {
  push?: NotificationDeps["channels"][Channel];
  email?: NotificationDeps["channels"][Channel];
}

/** Dispatch deps backed by a store: in_app persists a Notification row; push/email are injected. */
export function notificationDepsFromStore(store: NotificationStore, extra: ExtraChannels = {}): NotificationDeps {
  return {
    rules: (event) => store.rules(event),
    channels: {
      in_app: (userId, n) => store.create(userId, n),
      ...(extra.push ? { push: extra.push } : {}),
      ...(extra.email ? { email: extra.email } : {}),
    },
  };
}

let cached: NotificationStore | undefined;

/** Process-wide Prisma-backed store (lazy; never touches the DB at import time). */
export async function getNotificationStore(): Promise<NotificationStore> {
  if (!cached) {
    const { getPrisma } = await import("./db.ts");
    cached = createPrismaNotificationStore((await getPrisma()) as unknown as NotificationPrismaLike);
  }
  return cached;
}
