// Client-side helpers: the storefront has no session cookie, members paste the
// users-service bearer token. This only DISPLAYS roles (nav); servers verify the token.

import type { NavIdentity } from "./nav.ts";

export const TOKEN_KEY = "canna.token";

/** Decode a JWT payload without verifying it. Display-only; returns null when malformed. */
export function decodeClaims(token: string): Record<string, unknown> | null {
  const part = token.split(".")[1];
  if (!part) return null;
  try {
    const b64 = part.replace(/-/g, "+").replace(/_/g, "/");
    const json = typeof atob === "function" ? atob(b64) : Buffer.from(b64, "base64").toString("utf8");
    const v = JSON.parse(json);
    return v && typeof v === "object" ? (v as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

/** Map claims onto nav roles using the same flags the server accepts. */
export function navIdentityFromToken(token: string): NavIdentity | null {
  const c = decodeClaims(token);
  if (!c) return null;
  const scopes = new Set(typeof c.scope === "string" ? c.scope.split(/\s+/).filter(Boolean) : []);
  const roles = (c.roles && typeof c.roles === "object" ? c.roles : {}) as Record<string, unknown>;
  const admin = scopes.has("admin") || roles.admin === true || c.isAdmin === true;
  const vendor = scopes.has("vendor") || roles.vendor === true || c.vendorEnabled === true;
  const wholesale = scopes.has("wholesale") || roles.wholesale === true || c.wholesaleEnabled === true;
  const explicitRetail = scopes.has("retail") || roles.retail === true || c.retailEnabled === true;
  const any = admin || vendor || wholesale || explicitRetail || typeof c.retailEnabled === "boolean";
  return { retail: explicitRetail || !any, wholesale, vendor, admin };
}
