import { requireRole } from "@/lib/auth/requireRole";
import { getNotificationStore } from "@/lib/notificationStore";

export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const auth = await requireRole(request, "authenticated");
  if (!auth.ok) return auth.response;
  const store = await getNotificationStore();
  const [notifications, unread] = await Promise.all([
    store.list(auth.identity.sub),
    store.unreadCount(auth.identity.sub),
  ]);
  return Response.json({ notifications, unread });
}

/** Body: { ids?: string[] }. Marks those (or all) of the caller's notifications read. */
export async function PATCH(request: Request) {
  const auth = await requireRole(request, "authenticated");
  if (!auth.ok) return auth.response;
  let ids: string[] | undefined;
  try {
    const body = (await request.json()) as { ids?: unknown };
    if (Array.isArray(body.ids)) ids = body.ids.filter((i): i is string => typeof i === "string");
  } catch {
    /* empty body = mark all */
  }
  const updated = await (await getNotificationStore()).markRead(auth.identity.sub, ids);
  return Response.json({ updated });
}
