// Per-vendor driver registry. A vendor org configures its POS / ERP driver by
// storing a VendorIntegrationCredential row (encrypted, vault format). This
// module reads those rows and returns the driver that vendor configured, wired
// to a vault scoped to that one vendor's credential, so one vendor's secrets are
// never visible to another vendor's driver and no env fallback is used.
//
// Plaintext credential format (after decrypt): either a JSON object of secret
// names (e.g. {"TREEZ_CLIENT_ID":"..","TREEZ_CLIENT_SECRET":".."}) or a bare
// string, taken as the driver's primary key (DUTCHIE_API_KEY etc.).
//
// The store is injected, so tests use an in-memory store or a fake Prisma.

import { decryptSecret, type SecretReader } from "../lib/vault.ts";
import { getPosDriver, type FetchLike as PosFetch, type PosDriver } from "./pos.ts";
import { getErpDriver, type FetchLike as ErpFetch, type ErpDriver } from "./erp.ts";

export type PosDriverKind = "DUTCHIE_POS" | "TREEZ_POS";
export type ErpDriverKind = "DISTRU_ERP" | "LEAFLINK_ERP";

export interface VendorCredentialRow {
  driver: string;
  ciphertext: string;
  updatedAt?: Date;
}

export interface VendorCredentialStore {
  listForVendor(vendorId: string): Promise<VendorCredentialRow[]>;
}

export class DriverNotConfiguredError extends Error {
  readonly vendorId: string;
  readonly category: "pos" | "erp";
  constructor(vendorId: string, category: "pos" | "erp") {
    super(`vendor ${vendorId} has no ${category.toUpperCase()} driver configured`);
    this.name = "DriverNotConfiguredError";
    this.vendorId = vendorId;
    this.category = category;
  }
}

const POS_DRIVERS: Record<PosDriverKind, { kind: "dutchie" | "treez"; primaryKey: string }> = {
  DUTCHIE_POS: { kind: "dutchie", primaryKey: "DUTCHIE_API_KEY" },
  TREEZ_POS: { kind: "treez", primaryKey: "TREEZ_CLIENT_SECRET" },
};
const ERP_DRIVERS: Record<ErpDriverKind, { kind: "distru" | "leaflink"; primaryKey: string }> = {
  DISTRU_ERP: { kind: "distru", primaryKey: "DISTRU_API_KEY" },
  LEAFLINK_ERP: { kind: "leaflink", primaryKey: "LEAFLINK_API_KEY" },
};

export interface RegistryDeps {
  store: VendorCredentialStore;
  masterKey: string;
  fetchImpl?: PosFetch & ErpFetch;
}

/** Vault scoped to one credential row's decrypted secrets. */
function scopedVault(plaintext: string, primaryKey: string): SecretReader {
  let map: Record<string, string> = {};
  try {
    const parsed = JSON.parse(plaintext);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      for (const [k, v] of Object.entries(parsed)) if (typeof v === "string" && v) map[k] = v;
    } else {
      map = { [primaryKey]: plaintext };
    }
  } catch {
    map = { [primaryKey]: plaintext };
  }
  return { get: async (key) => map[key] };
}

/** Newest configured row among the allowed drivers (deterministic when several exist). */
function pick(rows: VendorCredentialRow[], allowed: string[]): VendorCredentialRow | undefined {
  return rows
    .filter((r) => allowed.includes(r.driver))
    .sort((a, b) => (b.updatedAt?.getTime() ?? 0) - (a.updatedAt?.getTime() ?? 0))[0];
}

export function createDriverRegistry(deps: RegistryDeps) {
  return {
    /** The POS driver this vendor configured. Throws DriverNotConfiguredError if none. */
    async posDriverFor(vendorId: string): Promise<PosDriver> {
      const row = pick(await deps.store.listForVendor(vendorId), Object.keys(POS_DRIVERS));
      if (!row) throw new DriverNotConfiguredError(vendorId, "pos");
      const spec = POS_DRIVERS[row.driver as PosDriverKind];
      const vault = scopedVault(decryptSecret(row.ciphertext, deps.masterKey), spec.primaryKey);
      return getPosDriver(spec.kind, vault, deps.fetchImpl);
    },
    /** The ERP driver this vendor configured. Throws DriverNotConfiguredError if none. */
    async erpDriverFor(vendorId: string): Promise<ErpDriver> {
      const row = pick(await deps.store.listForVendor(vendorId), Object.keys(ERP_DRIVERS));
      if (!row) throw new DriverNotConfiguredError(vendorId, "erp");
      const spec = ERP_DRIVERS[row.driver as ErpDriverKind];
      const vault = scopedVault(decryptSecret(row.ciphertext, deps.masterKey), spec.primaryKey);
      return getErpDriver(spec.kind, vault, deps.fetchImpl);
    },
  };
}

export type DriverRegistry = ReturnType<typeof createDriverRegistry>;

/** Minimal Prisma surface the store needs (lets tests pass a fake). */
export interface VendorCredentialDb {
  vendorIntegrationCredential: {
    findMany(args: { where: { vendorId: string } }): Promise<{ driver: string; credential: string; updatedAt: Date }[]>;
  };
}

export function createPrismaVendorCredentialStore(db: VendorCredentialDb): VendorCredentialStore {
  return {
    async listForVendor(vendorId) {
      const rows = await db.vendorIntegrationCredential.findMany({ where: { vendorId } });
      return rows.map((r) => ({ driver: String(r.driver), ciphertext: r.credential, updatedAt: r.updatedAt }));
    },
  };
}

/** Production wiring: lazy shared Prisma client + INTEGRATION_VAULT_KEY. */
export async function createDefaultDriverRegistry(fetchImpl?: PosFetch & ErpFetch): Promise<DriverRegistry> {
  const { getPrisma } = await import("../lib/db.ts");
  const db = (await getPrisma()) as unknown as VendorCredentialDb;
  return createDriverRegistry({
    store: createPrismaVendorCredentialStore(db),
    masterKey: process.env.INTEGRATION_VAULT_KEY ?? "",
    fetchImpl,
  });
}
