import { test } from "node:test";
import assert from "node:assert/strict";
import { createDriverRegistry, createPrismaVendorCredentialStore, DriverNotConfiguredError } from "../src/drivers/registry.ts";
import { encryptSecret } from "../src/lib/vault.ts";

const KEY = "k".repeat(32);

// Fake Prisma: only vendorIntegrationCredential.findMany, filtered by vendorId.
function fakeDb(rows: { vendorId: string; driver: string; plain: string; updatedAt?: Date }[]) {
  return {
    vendorIntegrationCredential: {
      async findMany({ where }: { where: { vendorId: string } }) {
        return rows
          .filter((r) => r.vendorId === where.vendorId)
          .map((r) => ({ driver: r.driver, credential: encryptSecret(r.plain, KEY), updatedAt: r.updatedAt ?? new Date(0) }));
      },
    },
  };
}

function recorder(routes: Record<string, unknown>) {
  const calls: { url: string; headers?: Record<string, string> }[] = [];
  const f = async (url: string, init?: any) => {
    calls.push({ url, headers: init?.headers });
    const body = routes[`${init?.method ?? "GET"} ${url}`];
    return body === undefined ? { ok: false, status: 404, json: async () => ({}) } : { ok: true, status: 200, json: async () => body };
  };
  return { f, calls };
}

const mk = (rows: Parameters<typeof fakeDb>[0], f?: any) =>
  createDriverRegistry({ store: createPrismaVendorCredentialStore(fakeDb(rows)), masterKey: KEY, fetchImpl: f });

