  const reg = mk([
    { vendorId: "a", driver: "DUTCHIE_POS", plain: "dk" },
    { vendorId: "b", driver: "TREEZ_POS", plain: JSON.stringify({ TREEZ_CLIENT_ID: "i", TREEZ_CLIENT_SECRET: "s" }) },
  ]);
  assert.equal((await reg.posDriverFor("a")).kind, "dutchie");
  assert.equal((await reg.posDriverFor("b")).kind, "treez");
});

