// Vendor applications: captures a state licence number, issuing state and
// expiry, and holds the application in a manual licence-validity check (a hard
// gate) until an admin approves it. No automated lookup against the state
// register for MVP. Licence expiry revokes listing rights.
//
// Persistence goes through an injectable VendorApplicationStore. The default
// store is Prisma-backed (VendorApplication + Vendor rows, loaded lazily so
// `node --test` never touches a database); tests inject the in-memory store or
// a fake Prisma client.

export type VendorApplicationStatus = "submitted" | "licence_check_pending" | "approved" | "rejected" | "expired";

export interface VendorApplication {
  id: string;
  vendorId?: string;
  businessName: string;
  stateLicenceNumber: string;
  issuingState: string;
  licenceExpiry: string;
  status: VendorApplicationStatus;
  createdAt: string;
  reviewedAt?: string;
  reviewerNote?: string;
}

export interface VendorApplicationInput {
  businessName: string;
  stateLicenceNumber: string;
  issuingState: string;
  licenceExpiry: string;
}

/** Persistence port. */
export interface VendorApplicationStore {
  insert(app: Omit<VendorApplication, "id" | "vendorId">): Promise<VendorApplication>;
  get(id: string): Promise<VendorApplication | undefined>;
  list(status?: VendorApplicationStatus): Promise<VendorApplication[]>;
  update(id: string, patch: Partial<Pick<VendorApplication, "status" | "reviewedAt" | "reviewerNote">>): Promise<VendorApplication | undefined>;
}

// ---- In-memory store (tests, local dev) ------------------------------------

export function createMemoryVendorApplicationStore(): VendorApplicationStore & { clear(): void } {
  let rows: VendorApplication[] = [];
  let n = 0;
  return {
    clear() {
      rows = [];
    },
    async insert(app) {
      const row: VendorApplication = { ...app, id: `app_${++n}_${Math.random().toString(36).slice(2, 6)}` };
      rows.push(row);
      return { ...row };
    },
    async get(id) {
      const r = rows.find((x) => x.id === id);
      return r ? { ...r } : undefined;
    },
    async list(status) {
      return rows.filter((a) => !status || a.status === status).map((a) => ({ ...a }));
    },
    async update(id, patch) {
      const r = rows.find((x) => x.id === id);
      if (!r) return undefined;
      Object.assign(r, patch);
      return { ...r };
    },
  };
}

// ---- Prisma store ----------------------------------------------------------

type DbStatus = "SUBMITTED" | "LICENCE_CHECK_PENDING" | "APPROVED" | "REJECTED" | "EXPIRED";

interface DbRow {
  id: string;
  vendorId: string;
  businessName: string;
  stateLicenceNumber: string;
  issuingState: string;
  licenceExpiry: Date;
  status: DbStatus;
  reviewedAt: Date | null;
  reviewerNote: string | null;
  createdAt: Date;
}

/** Structural view of the generated Prisma client (only what the store uses). */
export interface VendorApplicationPrisma {
  vendorApplication: {
    create(args: unknown): Promise<DbRow>;
    findUnique(args: unknown): Promise<DbRow | null>;
    findMany(args: unknown): Promise<DbRow[]>;
    update(args: unknown): Promise<DbRow>;
  };
}

const toDbStatus = (s: VendorApplicationStatus): DbStatus => s.toUpperCase() as DbStatus;
const fromDbStatus = (s: DbStatus): VendorApplicationStatus => s.toLowerCase() as VendorApplicationStatus;

function fromRow(r: DbRow): VendorApplication {
  const app: VendorApplication = {
    id: r.id,
    vendorId: r.vendorId,
    businessName: r.businessName,
    stateLicenceNumber: r.stateLicenceNumber,
    issuingState: r.issuingState,
    licenceExpiry: r.licenceExpiry.toISOString().slice(0, 10),
    status: fromDbStatus(r.status),
    createdAt: r.createdAt.toISOString(),
  };
  if (r.reviewedAt) app.reviewedAt = r.reviewedAt.toISOString();
  if (r.reviewerNote) app.reviewerNote = r.reviewerNote;
  return app;
}

export function createPrismaVendorApplicationStore(getClient: () => Promise<VendorApplicationPrisma>): VendorApplicationStore {
  return {
    async insert(app) {
      const db = await getClient();
      // A Vendor row is created with the application (1:1, VendorApplication.vendorId is unique).
      const row = await db.vendorApplication.create({
        data: {
          businessName: app.businessName,
          stateLicenceNumber: app.stateLicenceNumber,
          issuingState: app.issuingState,
          licenceExpiry: new Date(app.licenceExpiry),
          status: toDbStatus(app.status),
          vendor: { create: { name: app.businessName, state: app.issuingState } },
        },
      });
      return fromRow(row);
    },
    async get(id) {
      const db = await getClient();
      const row = await db.vendorApplication.findUnique({ where: { id } });
      return row ? fromRow(row) : undefined;
    },
    async list(status) {
      const db = await getClient();
      const rows = await db.vendorApplication.findMany({
        where: status ? { status: toDbStatus(status) } : {},
        orderBy: { createdAt: "asc" },
      });
      return rows.map(fromRow);
    },
    async update(id, patch) {
      const db = await getClient();
      const existing = await db.vendorApplication.findUnique({ where: { id } });
      if (!existing) return undefined;
      const data: Record<string, unknown> = {};
      if (patch.status) data.status = toDbStatus(patch.status);
      if (patch.reviewedAt) data.reviewedAt = new Date(patch.reviewedAt);
      if (patch.reviewerNote !== undefined) data.reviewerNote = patch.reviewerNote;
      return fromRow(await db.vendorApplication.update({ where: { id }, data }));
    },
  };
}

// ---- Service ---------------------------------------------------------------

function parseExpiry(value: string, now: Date): Date {
  if (!/^\d{4}-\d{2}-\d{2}/.test(value)) throw new Error("licenceExpiry must be an ISO date (YYYY-MM-DD)");
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) throw new Error("licenceExpiry is not a valid date");
  if (d.getTime() <= now.getTime()) throw new Error("licenceExpiry must be in the future");
  return d;
}

export function createVendorApplicationService(store: VendorApplicationStore) {
  return {
    store,

    list: (status?: VendorApplicationStatus) => store.list(status),

    /** The admin approval queue: applications awaiting the manual licence check. */
    listPendingQueue: () => store.list("licence_check_pending"),

    /**
     * Submit a vendor application. It immediately enters `licence_check_pending`
     * because admin approval requires a manual licence-validity check as a hard
     * gate before the vendor may list products.
     */
    async submit(input: VendorApplicationInput, now: Date = new Date()): Promise<VendorApplication> {
      if (!input.businessName || !input.stateLicenceNumber || !input.issuingState || !input.licenceExpiry) {
        throw new Error("businessName, stateLicenceNumber, issuingState and licenceExpiry are required");
      }
      if (!/^[A-Za-z]{2}$/.test(input.issuingState)) throw new Error("issuingState must be a two-letter state code");
      parseExpiry(input.licenceExpiry, now);
      return store.insert({
        businessName: input.businessName,
        stateLicenceNumber: input.stateLicenceNumber,
        issuingState: input.issuingState.toUpperCase(),
        licenceExpiry: input.licenceExpiry,
        status: "licence_check_pending",
        createdAt: now.toISOString(),
      });
    },

    /**
     * Admin approval after the manual licence check. `licenceChecked` must be true:
     * the admin attests the licence was validated against the state register by hand.
     * Only pending applications may be approved.
     */
    async approve(id: string, opts: { licenceChecked?: boolean; now?: Date } = {}): Promise<VendorApplication | undefined> {
      const app = await store.get(id);
      if (!app) return undefined;
      const now = opts.now ?? new Date();
      if (app.status !== "licence_check_pending") throw new Error(`cannot approve an application that is ${app.status}`);
      if (opts.licenceChecked !== true) throw new Error("manual licence check must be confirmed before approval");
      if (new Date(app.licenceExpiry).getTime() <= now.getTime()) {
        await store.update(id, { status: "expired", reviewedAt: now.toISOString() });
        throw new Error("licence has expired; vendor must resubmit");
      }
      return store.update(id, { status: "approved", reviewedAt: now.toISOString() });
    },

    /** Admin rejection after the manual licence check. */
    async reject(id: string, note?: string, now: Date = new Date()): Promise<VendorApplication | undefined> {
      const app = await store.get(id);
      if (!app) return undefined;
      return store.update(id, { status: "rejected", reviewedAt: now.toISOString(), ...(note ? { reviewerNote: note } : {}) });
    },

    /** Flip approved applications whose licence has lapsed to `expired`. Returns the ids changed. */
    async expireLapsed(now: Date = new Date()): Promise<string[]> {
      const changed: string[] = [];
      for (const a of await store.list("approved")) {
        if (new Date(a.licenceExpiry).getTime() <= now.getTime()) {
          await store.update(a.id, { status: "expired" });
          changed.push(a.id);
        }
      }
      return changed;
    },

    /** Hard gate: a vendor may list products only with an approved application and an unexpired licence. */
    async canVendorList(id: string, now: Date = new Date()): Promise<boolean> {
      const a = await store.get(id);
      return !!a && a.status === "approved" && new Date(a.licenceExpiry).getTime() > now.getTime();
    },
  };
}

export type VendorApplicationService = ReturnType<typeof createVendorApplicationService>;

// ---- Default (runtime) service: Prisma-backed, loaded lazily ---------------

let defaultService: VendorApplicationService | undefined;

export function getVendorApplicationService(): VendorApplicationService {
  defaultService ??= createVendorApplicationService(
    createPrismaVendorApplicationStore(async () => {
      const { getPrisma } = await import("./db.ts");
      return (await getPrisma()) as unknown as VendorApplicationPrisma;
    }),
  );
  return defaultService;
}

/** Test seam: replace (or clear with undefined) the default service. */
export function setVendorApplicationService(service: VendorApplicationService | undefined): void {
  defaultService = service;
}
