// HTTP handlers for the wholesale bulk-order and settle routes. Gated exactly
// like /api/wholesale/catalog: a verified token, the wholesale role and a second
// factor (amr totp/backup). B2B_REQUIRES_LICENCE is enforced by the service on
// submit and again at payment. Deps are injected so tests run without Next.

import { TokenVerificationError, type VerifiedClaims } from "./auth.ts";
import { assertWholesaleAccess, WholesaleError, type B2BRail, type WholesaleService } from "./wholesale.ts";

export interface WholesaleHttpDeps {
  /** Verify the request's bearer token; throw TokenVerificationError when absent/invalid. */
  authenticate(request: Request): Promise<VerifiedClaims>;
  service: WholesaleService;
}

function fail(err: unknown): Response {
  if (err instanceof WholesaleError) {
    const status =
      err.code === "not_found" ? 404
      : err.code === "not_wholesale_buyer" || err.code === "two_factor_required" || err.code === "forbidden" ? 403
      : err.code === "B2B_REQUIRES_LICENCE" ? 403
      : err.code === "invalid_transition" ? 409
      : 400;
    return Response.json({ error: err.code, error_description: err.message }, { status });
  }
  if (err instanceof TokenVerificationError) {
    return Response.json({ error: err.code, error_description: err.message }, { status: 401 });
  }
  throw err;
}

async function gate(request: Request, deps: WholesaleHttpDeps): Promise<VerifiedClaims> {
  const claims = await deps.authenticate(request);
  assertWholesaleAccess(claims);
  return claims;
}

/** POST /api/wholesale/orders  body { lines: [{ sku, quantity }] }: create and submit (licence gate). */
export async function handleBulkOrder(request: Request, deps: WholesaleHttpDeps): Promise<Response> {
  try {
    const claims = await gate(request, deps);
    const body = (await request.json().catch(() => null)) as { lines?: unknown } | null;
    if (!body || !Array.isArray(body.lines)) throw new WholesaleError("bad_request", "JSON body with a lines array required");
    const lines = body.lines.map((l) => {
      const r = (l ?? {}) as Record<string, unknown>;
      return { sku: String(r.sku ?? ""), quantity: Number(r.quantity) };
    });
    const order = deps.service.createBulkOrder(claims.sub, lines);
    try {
      await deps.service.submit(order.id);
    } catch (err) {
      // The draft stays recorded so the buyer can retry once the licence is fixed.
      if (err instanceof WholesaleError && err.code === "B2B_REQUIRES_LICENCE") {
        return Response.json({ error: err.code, error_description: err.message, order }, { status: 403 });
      }
      throw err;
    }
    return Response.json({ order }, { status: 201 });
  } catch (err) {
    return fail(err);
  }
}

/** POST /api/wholesale/orders/:id/settle  body { rail: "ach" | "terms" }: settle on a B2B rail, push to ERP. */
export async function handleSettle(request: Request, orderId: string, deps: WholesaleHttpDeps): Promise<Response> {
  try {
    const claims = await gate(request, deps);
    const body = (await request.json().catch(() => null)) as { rail?: unknown } | null;
    const existing = deps.service.must(orderId);
    if (existing.buyerId !== claims.sub) throw new WholesaleError("forbidden", "order belongs to another buyer");
    const order = await deps.service.payAndPush(orderId, String(body?.rail ?? "") as B2BRail);
    return Response.json({ order });
  } catch (err) {
    return fail(err);
  }
}
