// Process-wide wholesale service for the HTTP routes. External rails are the
// sandbox/recorded adapters until vendor ERP credentials and a live B2B rail
// are configured; the licence check reads the compliance licence store.

import { createWholesaleService, type BuyerLicenceStatus, type WholesaleService } from "./wholesale.ts";

/** Map the compliance engine's verification onto the buyer licence status the order gate expects. */
export function toBuyerLicenceStatus(v: { active: boolean; reason?: "EXPIRED" | "UNAPPROVED" | "NOT_FOUND" }): BuyerLicenceStatus {
  if (v.active) return "VERIFIED";
  if (v.reason === "EXPIRED") return "EXPIRED";
  if (v.reason === "UNAPPROVED") return "PENDING";
  return "UNVERIFIED";
}

let service: WholesaleService | undefined;

export function getWholesaleService(): WholesaleService {
  service ??= createWholesaleService({
    erp: { pushOrder: async (o) => ({ erpRef: `sandbox-erp-${o.id}` }) },
    settle: async (order, rail) => ({ ref: `sandbox-${rail}-${order.id}` }),
    licenceStatusOf: async (buyerId) => {
      const { verifyVendorLicense } = await import("./compliance/license.ts");
      return toBuyerLicenceStatus(await verifyVendorLicense(buyerId));
    },
  });
  return service;
}

export function setWholesaleService(s: WholesaleService | undefined): void {
  service = s;
}
