// 20-minute plan-review clock (Q16). Objective start/stop, deadline, escalation, logged refund decision.
// Objective = every timestamp comes from the server clock (app.now); the API accepts no client times.
import { requireRole } from '../../core/auth.js'
import { audit, tx, kpi, HttpError } from '../../core/db.js'
import { uid } from '../../lib/crypto.js'
import { getNotifyAdapter } from './notify.js'

export const REVIEW_LIMIT_MS = 20 * 60_000

export function registerReviewClock({ route, app }) {
  const { db } = app
  const get = id => {
    const r = db.prepare('SELECT * FROM scheduling_plan_reviews WHERE id = ?').get(id)
    if (!r) throw new HttpError(404, 'Plan review not found')
    return r
  }
  const view = r => ({
    ...r,
    remaining_ms: r.status === 'running' ? Math.max(0, r.deadline_at - app.now()) : null,
    overdue: r.status === 'running' && app.now() > r.deadline_at
  })

  /** Escalate every running review past its deadline. Idempotent; returns escalated ids. */
  function sweep() {
    const now = app.now()
    const late = db.prepare("SELECT * FROM scheduling_plan_reviews WHERE status = 'running' AND deadline_at < ?").all(now)
    for (const r of late) {
      db.prepare("UPDATE scheduling_plan_reviews SET status = 'escalated', escalated_at = ? WHERE id = ? AND status = 'running'").run(now, r.id)
      audit(db, { action: 'scheduling.review_escalated', target: r.id, detail: { deadline_at: r.deadline_at } })
      kpi(db, 'plan_review_escalated', {})
      getNotifyAdapter().notify(`Plan review overdue (20 min): ${r.customer_name}. Refund decision needed.`, { priority: 5, tags: ['warning'] })
    }
    return late.map(r => r.id)
  }
  app.sweepPlanReviews = sweep

  route('POST', '/api/scheduling/reviews', ({ body }) => {
    const { customer_name, booking_id, order_id } = body
    if (!customer_name) throw new HttpError(400, 'customer_name is required')
    if (booking_id && !db.prepare('SELECT 1 FROM scheduling_bookings WHERE id = ?').get(booking_id)) throw new HttpError(404, 'Booking not found')
    const id = uid('pr')
    db.prepare('INSERT INTO scheduling_plan_reviews (id, booking_id, order_id, customer_name, status, requested_at) VALUES (?, ?, ?, ?, ?, ?)')
      .run(id, booking_id || null, order_id || null, String(customer_name), 'requested', app.now())
    audit(db, { action: 'scheduling.review_requested', target: id })
    return view(get(id))
  })

  route('POST', '/api/scheduling/reviews/:id/start', ({ token, params }) => {
    const u = requireRole(db, token, 'tech')
    return tx(db, () => {
      const r = get(params.id)
      if (r.status !== 'requested') throw new HttpError(409, 'Review clock already started')
      const now = app.now()
      db.prepare('INSERT OR IGNORE INTO scheduling_techs (user_id, duty_state, duty_updated_at, created_at) VALUES (?, ?, ?, ?)').run(u.id, 'off', now, now)
      db.prepare("UPDATE scheduling_plan_reviews SET status = 'running', tech_id = ?, started_at = ?, deadline_at = ? WHERE id = ?")
        .run(u.id, now, now + REVIEW_LIMIT_MS, params.id)
      audit(db, { actorId: u.id, action: 'scheduling.review_started', target: params.id, detail: { deadline_at: now + REVIEW_LIMIT_MS } })
      return view(get(params.id))
    })
  })

  route('POST', '/api/scheduling/reviews/:id/stop', ({ token, params }) => {
    const u = requireRole(db, token, 'tech')
    return tx(db, () => {
      const r = get(params.id)
      if (r.status !== 'running' && r.status !== 'escalated') throw new HttpError(409, 'Review clock is not running')
      if (r.stopped_at) throw new HttpError(409, 'Review clock already stopped')
      const now = app.now()
      const duration = now - r.started_at
      const within = duration <= REVIEW_LIMIT_MS ? 1 : 0
      // A late stop stays 'escalated' (decision still owed); an on-time stop completes.
      const status = within ? 'completed' : 'escalated'
      db.prepare('UPDATE scheduling_plan_reviews SET status = ?, stopped_at = ?, duration_ms = ?, within_limit = ?, escalated_at = COALESCE(escalated_at, ?) WHERE id = ?')
        .run(status, now, duration, within, within ? null : now, params.id)
      audit(db, { actorId: u.id, action: 'scheduling.review_stopped', target: params.id, detail: { duration_ms: duration, within_limit: !!within } })
      if (!within) getNotifyAdapter().notify(`Plan review ran ${Math.round(duration / 60_000)} min (limit 20): ${r.customer_name}. Refund decision needed.`, { priority: 5, tags: ['warning'] })
      return view(get(params.id))
    })
  })

  route('GET', '/api/scheduling/reviews/:id', ({ token, params }) => {
    requireRole(db, token, 'tech')
    sweep()
    return view(get(params.id))
  })

  route('GET', '/api/scheduling/admin/reviews', ({ token, query }) => {
    requireRole(db, token, 'tech')
    sweep()
    const rows = query.status
      ? db.prepare('SELECT * FROM scheduling_plan_reviews WHERE status = ? ORDER BY requested_at').all(query.status)
      : db.prepare('SELECT * FROM scheduling_plan_reviews ORDER BY requested_at').all()
    return { reviews: rows.map(view) }
  })

  route('POST', '/api/scheduling/admin/reviews/sweep', ({ token }) => {
    requireRole(db, token, 'tech')
    return { escalated: sweep() }
  })

  // Logged refund decision. Required for any escalated review; records only, money moves via POST /api/orders/:id/refund.
  route('POST', '/api/scheduling/admin/reviews/:id/decision', ({ token, params, body }) => {
    const u = requireRole(db, token, 'admin')
    sweep()
    const { decision, amount_cents, reason } = body
    if (!['refund', 'no_refund'].includes(decision)) throw new HttpError(400, 'decision must be refund or no_refund')
    if (!reason || !String(reason).trim()) throw new HttpError(400, 'reason is required')
    if (decision === 'refund' && !(Number.isInteger(amount_cents) && amount_cents > 0)) throw new HttpError(400, 'amount_cents (positive integer) is required for refund')
    return tx(db, () => {
      const r = get(params.id)
      if (r.decision) throw new HttpError(409, 'Decision already logged')
      if (r.status === 'requested' || r.status === 'running') throw new HttpError(409, 'Review has not finished or escalated yet')
      const now = app.now()
      db.prepare('UPDATE scheduling_plan_reviews SET decision = ?, decision_amount_cents = ?, decision_reason = ?, decision_by = ?, decision_at = ? WHERE id = ?')
        .run(decision, decision === 'refund' ? amount_cents : null, String(reason), u.id, now, params.id)
      audit(db, { actorId: u.id, action: 'scheduling.review_decision', target: params.id, detail: { decision, amount_cents: decision === 'refund' ? amount_cents : null, reason: String(reason), order_id: r.order_id } })
      kpi(db, 'plan_review_decision', { decision })
      return view(get(params.id))
    })
  })
}
