import { test, expect, type APIRequestContext } from "@playwright/test";
import { signIn, bearer, COMMERCE_URL } from "./auth";

const UNIT = 14;
const TAG = `u${UNIT}-${Date.now()}`;
const BUYER = "retail-bronze@ecom.test";
const REFERENCE = `bank-ref-${TAG}`;
const api = (p: string) => `${COMMERCE_URL}${p}`;

const s: { admin?: string; vendor?: string; buyer?: string; vendorId?: string; payoutId?: string; payoutAmount?: number; setupError?: string } = {};

async function fundVendor(request: APIRequestContext) {
  const vendorRes = await request.get(api("/api/vendors/me"), { headers: bearer(s.vendor!) });
  expect(vendorRes.status()).toBe(200);
  s.vendorId = ((await vendorRes.json()) as { vendor: { id: string } }).vendor.id;

  const prod = await request.post(api("/api/vendors/products"), {
    headers: bearer(s.vendor!),
    data: { name: `${TAG} payout widget`, description: "S6 payout test", basePrice: 2000, currency: "usd", category: "s6-e2e" },
  });
  expect(prod.status(), await prod.text()).toBe(201);
  const productId = ((await prod.json()) as { product: { id: string } }).product.id;

  const cart = await request.get(api("/api/cart"), { headers: bearer(s.buyer!) });
  for (const line of ((await cart.json()) as { lines: Array<{ id: string }> }).lines) {
    await request.delete(api(`/api/cart?lineId=${line.id}`), { headers: bearer(s.buyer!) });
  }
  const add = await request.post(api("/api/cart"), { headers: bearer(s.buyer!), data: { productId, quantity: 1 } });
  expect(add.status(), await add.text()).toBe(200);
  const order = await request.post(api("/api/orders"), { headers: bearer(s.buyer!), data: { shippingAddress: `${TAG} 1 Test St, Makati` } });
  expect(order.status(), await order.text()).toBe(201);
  const orderId = ((await order.json()) as { order: { id: string } }).order.id;
  const pay = await request.post(api("/api/payments/checkout"), { headers: bearer(s.buyer!), data: { masterOrderId: orderId, provider: "crypto_mock" } });
  expect(pay.status(), await pay.text()).toBe(201);
  const settle = await request.post(api("/api/payments/mock/confirm"), {
    headers: bearer(s.buyer!),
    data: { paymentRecordId: ((await pay.json()) as { paymentRecordId: string }).paymentRecordId },
  });
  expect(settle.status(), await settle.text()).toBe(200);
}

test.beforeAll(async ({ request }) => {
  s.admin = await signIn(request, "admin@ecom.test", "commerce", UNIT);
  s.vendor = await signIn(request, "vendor-a@ecom.test", "commerce", UNIT);
  s.buyer = await signIn(request, BUYER, "commerce", UNIT);
