  });
  expect(created.status(), await created.text()).toBe(201);
  const body = (await created.json()) as { payout?: { id: string; status: string }; id?: string; status?: string };
  const payout = body.payout ?? (body as { id: string; status: string });
  s.payoutId = payout.id;
