test("non-admin cannot execute a payout; unknown payout is 404", async ({ request }) => {
  needSetup();
  const denied = await request.post(api(`/api/ledger/payouts/${s.payoutId}/execute`), { headers: bearer(s.vendor!), data: { mode: "manual" } });
  expect(denied.status()).toBe(403);
  const missing = await request.post(api("/api/ledger/payouts/does-not-exist/execute"), { headers: bearer(s.admin!), data: { mode: "manual" } });
  expect(missing.status()).toBe(404);
});

test("rail mode is refused for a vendor without a connected account and the payout stays PENDING", async ({ request }) => {
  needSetup();
  const r = await request.post(api(`/api/ledger/payouts/${s.payoutId}/execute`), { headers: bearer(s.admin!), data: { mode: "rail" } });
  expect([400, 409]).toContain(r.status());
  const hist = await request.get(api(`/api/ledger/payouts/history?vendorId=${s.vendorId}&status=PENDING`), { headers: bearer(s.admin!) });
  const rows = ((await hist.json()) as { payouts: Array<{ id: string; status: string }> }).payouts;
  expect(rows.find((p) => p.id === s.payoutId)?.status).toBe("PENDING");
});

test("manual execute marks the payout COMPLETED with the reference; a repeat is idempotent", async ({ request }) => {
  needSetup();
  const exec = await request.post(api(`/api/ledger/payouts/${s.payoutId}/execute`), {
    headers: bearer(s.admin!),
    data: { mode: "manual", reference: REFERENCE },
  });
  expect(exec.status(), await exec.text()).toBe(200);
  const done = (await exec.json()) as { payout: { id: string; status: string; note: string | null }; alreadyCompleted: boolean };
  expect(done.payout.status).toBe("COMPLETED");
  expect(done.payout.note).toContain(REFERENCE);
  expect(done.alreadyCompleted).toBe(false);

  const again = await request.post(api(`/api/ledger/payouts/${s.payoutId}/execute`), { headers: bearer(s.admin!), data: { mode: "manual" } });
  expect(again.status()).toBe(200);
  expect(((await again.json()) as { alreadyCompleted: boolean }).alreadyCompleted).toBe(true);
});

test("history lists the completed payout, filterable by vendor and status, admin only", async ({ request }) => {
  needSetup();
  const hist = await request.get(api(`/api/ledger/payouts/history?vendorId=${s.vendorId}&status=COMPLETED`), { headers: bearer(s.admin!) });
  expect(hist.status()).toBe(200);
  const rows = ((await hist.json()) as { payouts: Array<{ id: string; vendorId: string; status: string; amountMinor: number }> }).payouts;
  const row = rows.find((p) => p.id === s.payoutId);
  expect(row, "completed payout in history").toBeTruthy();
  expect(row!.vendorId).toBe(s.vendorId);
  expect(row!.amountMinor).toBe(s.payoutAmount);
  for (const p of rows) expect(p.status).toBe("COMPLETED");

  const bad = await request.get(api("/api/ledger/payouts/history?status=NOPE"), { headers: bearer(s.admin!) });
  expect(bad.status()).toBe(400);
  const denied = await request.get(api("/api/ledger/payouts/history"), { headers: bearer(s.vendor!) });
  expect(denied.status()).toBe(403);
});
