/**
 * PM evidence writer for WebChat council runs (pm T-adbb5464).
 *
 * Turns a finished run's synthesis into a short, metadata-only evidence record
 * and persists it through an injected pm client. No answer text, prompt,
 * cookie, token or login detail ever enters the record: only who answered,
 * how long it took, and how the run ended. The client is injected so tests
 * (and callers without pm) need no network.
 */
import type { CouncilSynthesis } from './council.ts'

/** The slice of the pm API the writer needs. */
export interface PmEvidenceClient {
  /** Append a comment to a task; resolves when pm has stored it. */
  addComment(taskId: string, body: string): Promise<void>
}

/** Metadata-only record of one run. */
export interface CouncilEvidence {
  readonly runId: string
  readonly roundMode: 'single' | 'peer-review'
  readonly synthesizer: string
  readonly method: CouncilSynthesis['method']
  readonly members: readonly {
    readonly seat: string
    readonly provider: string
    readonly model: string
    readonly status: 'answered' | 'failed' | 'not-called'
    readonly ms: number
  }[]
  readonly dissenters: readonly string[]
  readonly unresolvedCount: number
  readonly consensusChars: number
}

/** Build the record, dropping every free-text field. */
export function buildCouncilEvidence(
  runId: string,
  roundMode: 'single' | 'peer-review',
  synthesizer: string,
  synthesis: CouncilSynthesis,
): CouncilEvidence {
  return {
    runId,
    roundMode,
    synthesizer,
    method: synthesis.method,
    members: synthesis.provenance.map(entry => ({
      seat: entry.seat,
      provider: entry.provider ?? entry.transport,
      model: entry.model ?? '',
      status: entry.status,
      ms: entry.ms,
    })),
    dissenters: synthesis.disagreements.map(entry => entry.seat),
    unresolvedCount: synthesis.unresolved.length,
    consensusChars: synthesis.consensus.length,
  }
}

/** Render the record as the comment pm stores. */
export function renderCouncilEvidence(evidence: CouncilEvidence): string {
  const lines = [
    `WebChat council run ${evidence.runId}: ${evidence.method}, ${evidence.roundMode}, synthesizer ${evidence.synthesizer}`,
    ...evidence.members.map(m => `- ${m.seat} (${m.provider}/${m.model || 'default'}): ${m.status}, ${m.ms} ms`),
    `dissent: ${evidence.dissenters.length === 0 ? 'none' : evidence.dissenters.join(', ')}; unresolved: ${evidence.unresolvedCount}; consensus ${evidence.consensusChars} chars`,
  ]
  return lines.join('\n')
}

/** Outcome of a persistence attempt. A pm outage never fails the run. */
export interface PersistResult {
  readonly persisted: boolean
  readonly error?: string | undefined
}

/**
 * Persist run evidence to the task. Refuses without a task id, and reports a
 * client failure instead of throwing, so the council result is never lost to a
 * reporting error.
 */
export async function persistCouncilEvidence(
  client: PmEvidenceClient | undefined,
  taskId: string | undefined,
  evidence: CouncilEvidence,
): Promise<PersistResult> {
  if (client === undefined) return { persisted: false, error: 'no pm client' }
  if (taskId === undefined || taskId === '') return { persisted: false, error: 'no task id' }
  try {
    await client.addComment(taskId, renderCouncilEvidence(evidence))
    return { persisted: true }
  } catch (error) {
    return { persisted: false, error: error instanceof Error ? error.message : String(error) }
  }
}
