    { seat: 'web-deepseek-web', name: 'DeepSeek', transport: 'webchat', provider: 'unlimitedchat', model: 'deepseek-web', status: 'failed', ms: 50, error: 'cookie=abc' },
  ],
} as unknown as CouncilSynthesis

describe('pm evidence', () => {
