    const addComment = vi.fn(async () => {})
    const result = await persistCouncilEvidence({ addComment }, 'T-1', buildCouncilEvidence('r1', 'single', 'tally', synthesis))
    expect(result.persisted).toBe(true)
    expect(addComment).toHaveBeenCalledWith('T-1', expect.stringContaining('single'))
  })
  it('reports, never throws, when pm is down, missing, or the task id is empty', async () => {
    const ev = buildCouncilEvidence('r1', 'single', 'tally', synthesis)
    const down = await persistCouncilEvidence({ addComment: async () => { throw new Error('ECONNREFUSED') } }, 'T-1', ev)
