/**
 * WebChat council panel (pm T-adbb5464).
 *
 * Shows the browser seats the host registered (never a hard-coded list), lets
 * the user pick the roster, round mode and synthesizer, says plainly why a run
 * may not start, and shows the last run per member with its provider/model
 * label, duration, failures, dissent and synthesis. It writes only the
 * council settings and never starts a run, spends, or signs in.
 */

import type { PropsLocale } from '@deepseek-ai/dsh-client-ui-slots'
import { useSyncExternalStore } from 'react'
import type { SettingsFace } from './CouncilBudget.tsx'
import { NS } from './locales.ts'
import {
  readRegistry, readRoster, readRoundMode, readSynthesizer, startGuard, synthesizerChoices,
  type RoundMode, type WebSeatState,
} from './web-council.ts'
import css from './WebChatCouncil.module.css'

/** One member of a finished run, as the host reports it. Carries no answer text. */
export interface WebCouncilMemberRun {
  readonly seat: string
  readonly provider: string
  readonly model: string
  readonly status: 'answered' | 'failed' | 'not-called'
  readonly ms: number
}

/** A finished run, for display. */
export interface WebCouncilRunView {
  readonly method: 'members' | 'insufficient-members'
  readonly synthesizer: string
  readonly members: readonly WebCouncilMemberRun[]
  readonly dissenters: readonly string[]
  readonly consensus: string
}

/** Props for the panel. */
export type WebChatCouncilProps = PropsLocale<typeof NS> & {
  settings: SettingsFace
  /** Whether the viewer's role may start a council. Defaults to allowed. */
  roleAllowed?: boolean
  /** The latest run, when there is one. */
  lastRun?: WebCouncilRunView | undefined
}

const STATE_KEY = {
  'ready': 'wc.ready',
  'requires-login': 'wc.requiresLogin',
  'unknown': 'wc.unknown',
  'unavailable': 'wc.unavailable',
} as const satisfies Record<WebSeatState, string>

const STATUS_KEY = { 'answered': 'wc.answered', 'failed': 'wc.failed', 'not-called': 'wc.notCalled' } as const

/**
 * The panel.
 * @param props - locale seat, council settings scope, role flag and last run.
 * @returns the panel.
 */
export function WebChatCouncil({ t, settings, roleAllowed = true, lastRun }: WebChatCouncilProps): JSX.Element {
  const snapshot = useSyncExternalStore(
    fn => settings.subscribe(fn),
    () => settings.getSnapshot(),
  )
  const section = snapshot.value
  const registry = readRegistry(section)
  const roster = readRoster(section, registry)
  const mode = readRoundMode(section)
  const synthesizer = readSynthesizer(section)
  const guard = startGuard(registry, roster, synthesizer, roleAllowed)
  const writable = snapshot.writable !== false && roleAllowed

  const picks = { ...(section?.['webSeats'] ?? {}) } as Record<string, { enabled?: boolean }>
  const toggle = (model: string): void => {
    void settings.set('webSeats', { ...picks, [model]: { ...picks[model], enabled: picks[model]?.enabled !== true } })
  }
  const failed = lastRun?.members.filter(member => member.status !== 'answered') ?? []

  return (
    <div className={css.panel} role="group" aria-label={t('wc.title')}>
      <strong className={css.title}>{t('wc.title')}</strong>
      {registry.length === 0 ? <div className={css.meta}>{t('wc.none')}</div> : null}
      {registry.map(entry => (
        <label key={entry.id} className={css.row}>
          <input type="checkbox" checked={roster.some(seat => seat.id === entry.id)}
            disabled={!writable || entry.state === 'unavailable'} onChange={() => { toggle(entry.model) }} />
          <span>{entry.displayName}</span>
          <span className={css.meta}>{entry.provider}/{entry.model} · {t(STATE_KEY[entry.state])}</span>
        </label>
      ))}
      <label className={css.row}>
        {t('wc.rounds')}{' '}
        <select value={mode} disabled={!writable}
          onChange={(event) => { void settings.set('roundMode', event.target.value as RoundMode) }}>
          <option value="single">{t('wc.single')}</option>
          <option value="peer-review">{t('wc.peer')}</option>
        </select>
      </label>
      <label className={css.row}>
        {t('wc.synth')}{' '}
        <select value={synthesizer} disabled={!writable}
          onChange={(event) => { void settings.set('webCouncilSynthesizer', event.target.value) }}>
          {synthesizerChoices(roster).map(choice => <option key={choice.id} value={choice.id}>{choice.label}</option>)}
        </select>
      </label>
      <div className={guard.ok ? css.meta : css.warn} role="status">
        {guard.ok ? t('wc.canStart') : `${t('wc.cannotStart')}: ${guard.reason}`}
      </div>
      {lastRun === undefined ? null : (
        <div className={css.block}>
          <strong>{t('wc.last')}</strong>
          {lastRun.members.map(member => (
            <div key={member.seat} className={css.row}>
              <span>{member.seat}</span>
              <span className={css.meta}>
                {t('wc.source')}: {member.provider}/{member.model} · {t(STATUS_KEY[member.status])} · {member.ms} ms
              </span>
            </div>
          ))}
          {failed.length > 0 ? <div className={css.warn}>{t('wc.partial')}</div> : null}
          {lastRun.dissenters.length > 0 ? <div>{t('wc.dissent')}: {lastRun.dissenters.join(', ')}</div> : null}
          {lastRun.method === 'insufficient-members'
            ? <div className={css.warn}>{t('wc.insufficient')}</div>
            : <div>{t('wc.synthesis')} ({lastRun.synthesizer}): {lastRun.consensus}</div>}
        </div>
      )}
    </div>
  )
}
